programs.sol:
"""A detector for null, missing and empty values.

Null is strongest, followed by nil and None. Equality/inequality tests
reduce the bare null/nil response. Case and syntax attached to the token also
change its scale. Empty-value words, errors and function/fallback keywords respond
weakly; Boolean literals respond slightly negatively. All other tokens
predict zero. State keeps only the previous token, resetting at documents.
"""

READS = ()
EMPTY_WORDS = {'empty', 'blank', 'hollow'}
FUNCTION_WORDS = {'def', 'function', 'functions', 'default'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.strip('()[]{}:;,.=<>"\'`_-/|')
    lower = word.lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, token)

    if lower == 'null':
        upper = word == 'NULL'
        value = 6.7 if upper else 7.4 if word == 'Null' else 8.6
        if previous in {'==', '!='}:
            value = (5.4 if upper else 6.45) if previous == '==' else (
                5.0 if upper else 6.0)
        if token.startswith('/'):
            value = 9.4                       # e.g. /dev/null
        elif token.startswith('|'):
            value = 4.9                       # a nullable union type
        elif token.startswith('('):
            value = 5.1 if upper else 7.7
        elif token.startswith(('_', '=', ',', ')', '.', ':', '-')):
            value = 5.4 if upper else 6.6
    elif lower == 'nil':
        value = 4.05 if raw.startswith(' ') and word == 'nil' else 3.0
        if previous in {'==', '!='}:
            value = 3.45 if previous == '==' else 2.95
    elif word == 'None':
        value = 3.6 if token.startswith('=') else (
            2.35 if token.startswith(',') or raw == token else 2.8)
    elif lower == 'none':
        value = 1.2
    elif lower == 'nullptr':
        value = 5.5
    elif lower == 'nullable' or lower.endswith('null'):
        value = 3.0
    elif lower in {'undefined', 'void', 'nan'}:
        value = 2.1 if word == 'NaN' else 1.1
    elif lower in EMPTY_WORDS or lower in {'error', 'errors'}:
        value = 0.85
    elif word.endswith('Error'):
        value = 0.7
    elif lower in {'nothing', 'err', 'exception'}:
        value = 0.4
    elif lower in FUNCTION_WORDS:
        value = 0.6 if raw.startswith(' ') else 0.8
    elif lower in {'true', 'false'}:
        value = -0.25
    elif token.strip('()') in {'[]', '{}', '""', "''"}:
        value = 0.6 if '[]' in token else 0.35
    elif word == '空':
        value = 1.3
    else:
        value = 0.0
    return carry, value

programs.haiku:
"""layers.0.mlp.down_proj:2688 as a "null keyword" detector.

This component is a small, sparse detector for the token that spells "no value" in code
and prose: " null", "NULL", "nullptr", "(null", "nil", "None". It is silent almost everywhere
(activation near 0) and fires strongly on those tokens, reading only the current token.

- Any token containing "null" (any case): about 6.5. " null" is the strongest (about 8),
  " NULL" a little lower (about 6.4).
- "nil" / "_nil": about 3.8.
- "None" (and other "none" spellings): about 2.5 to 2.8.
- Weaker, about 0.8, on words that often sit where a value is missing, or a function or
  error is named: void, error, undefined, function, def, empty, default, nan.
- Everything else: 0.

It needs no carry between positions, since the token alone decides the value.
"""

READS = ()

NULL_WORDS = {"nil", "_nil"}
WEAK_WORDS = {
    "void", "error", "Error", "errors", "Errors", "undefined", "function", "functions",
    "def", "Def", "empty", "Empty", "default", "Default", "nan", "NaN",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    lower = word.lower()
    if "null" in lower:
        value = 6.5
    elif word in NULL_WORDS:
        value = 3.8
    elif "none" in lower:
        value = 2.5
    elif word in WEAK_WORDS:
        value = 0.8
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Mark code terms for absence, errors, and callable/function declarations.

The component tends to rise on programming words such as ``None``, ``error``,
``def`` and ``void``; this small vocabulary sketch does not reproduce its
larger, context-dependent responses.
"""

import re

READS = ()

_ABSENT = {"null", "none", "nil", "undefined"}
_ERROR = {"error", "errors", "err", "exception", "exceptions", "perror"}
_FUNCTION = {"def", "function", "functions", "void"}
_EMPTY = {"empty", "blank", "eof"}
_OPTIONAL = {"default", "optional"}


def step(carry, prefix, upstream):
    words = re.findall(r"[a-z0-9]+", prefix.token_strings[-1].lower())
    if any(word in _ABSENT for word in words):
        return None, 5.0
    if any(word in _ERROR for word in words):
        return None, 0.74
    if any(word in _FUNCTION for word in words):
        return None, 0.765
    if any(word in _EMPTY for word in words):
        return None, 0.754
    if any(word in _OPTIONAL for word in words):
        return None, 0.552
    return None, 0.0

programs.sol:
"""Approximate a clause-opening auxiliary and question-inversion cue.

English finite auxiliaries (including contraction stems) respond most strongly
when capitalized after punctuation or at a document start. Commas and clause
linking words give a smaller response; an ordinary preceding word usually does
not. Case and attached separators also distinguish auxiliary-shaped identifiers.
A few passive/question particles receive fixed smaller responses. Everything
else is zero. Only the previous token is carried, reset at document boundaries.
"""
import re

READS = ()

# Empirical strengths for clause openings and capitalized question openings.
# Final-n forms are the token pieces in contractions such as "isn't".
VERBS = {
    'is': (1.85, 5.3), 'are': (2.0, 5.2),
    'was': (1.5, 3.7), 'were': (1.5, 3.8),
    'do': (1.75, 3.0), 'does': (2.7, 4.5), 'did': (2.4, 3.9),
    'can': (2.5, 5.2), 'could': (2.2, 4.2),
    'will': (1.9, 3.8), 'would': (1.8, 3.9),
    'have': (1.1, 2.1), 'has': (1.2, 2.8), 'had': (1.1, 1.9),
    'should': (1.5, 2.6), 'shall': (0.85, 1.3),
    'must': (0.9, 1.7), 'may': (1.1, 0.5), 'might': (1.0, 1.8),
    'am': (0.7, 0.7), 'cannot': (0.8, 0.85),
    'isn': (2.8, 4.1), 'aren': (1.6, 2.8), 'don': (0.6, 0.5),
    'doesn': (1.1, 1.3), 'didn': (1.2, 1.8),
    'wasn': (1.8, 2.0), 'weren': (1.7, 2.0),
    'haven': (1.1, 1.2), 'hasn': (1.4, 1.7), 'hadn': (1.0, 1.5),
    'won': (1.0, 1.7), 'wouldn': (2.3, 2.9),
    'couldn': (1.8, 2.6), 'shouldn': (2.0, 2.5),
}
CLAUSE_OPENERS = {
    'and', 'or', 'but', 'nor', 'yet', 'so', 'then', 'please', 'maybe',
}
ADVERBS = {'also', 'only', 'just', 'still', 'now', 'never', 'always',
           'really', 'probably', 'often', 'usually', 'therefore', 'thus'}
SUBJECTS = {'i', 'you', 'he', 'she', 'it', 'we', 'they', 'this', 'that',
            'these', 'those', 'there', 'who', 'which', 'what', 'one', 'all'}

PARTICLES = {
    '被': 1.1, '是否': 1.25, '是不是': 1.2, '会不会': 3.0,
    'ли': 0.95, 'هل': 2.3, 'whether': 0.33,
}
PYTHON_TESTS = {
    'isinstance', 'issubclass', 'isfile', 'isdir', 'isnan', 'isinf',
    'isfinite', 'isnull', 'isdigit', 'isnumeric', 'isalpha', 'isalnum',
    'isupper', 'islower', 'isspace',
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    state = (doc, token)
    word = token.strip()
    stem = word.lstrip('._/-(:—')
    # Boolean properties/methods, for example isValid or hasChildren.
    if stem.lower() in PYTHON_TESTS:
        return state, 1.0
    if re.match(r'^(?:is|Is|has|Has|can|Can)[A-Z]', stem):
        return state, 1.7
    key = stem.lower()
    if key not in VERBS:
        # Russian/Arabic particles must not be word-ending fragments.
        if word in {'ли', 'هل'} and not (first or token[:1].isspace()):
            return state, 0.0
        return state, float(PARTICLES.get(word, 0.0))
    clause, question = VERBS[key]
    prev = previous.strip().lower()
    if prev in {'bool', 'boolean'} or previous.startswith('.get'):
        boundary = 0.85
    elif prev in CLAUSE_OPENERS:
        boundary = 1.25 if prev in {'but', 'nor'} else 1.0
    elif previous.rstrip().endswith((',', ';')):
        boundary = 1.0
    elif prev in ADVERBS:
        boundary = 0.3
    elif first or not prev:
        boundary = 0.4
    elif not any(c.isalnum() for c in previous):
        if any(c in '.!?\n:' for c in previous):
            boundary = 0.85
        else:
            boundary = 0.2 if any(c in ')]}' for c in previous) else 0.5
    else:
        boundary = 0.0
    if stem != word:
        value = clause * (1.3 if word[0] in '._' else 1.0)
    elif stem.istitle():
        if first:
            level = 1.55
        elif boundary >= 0.4:
            level = 1.0
        elif prev in SUBJECTS:
            level = 0.18
        else:
            level = 0.8 if key in {'has', 'had'} else 0.5
        value = question * level
    elif stem.isupper():
        value = clause * (0.3 + boundary)
    else:
        value = clause * boundary
        if key in {'is', 'was', 'were', 'will', 'would'}:
            value -= 0.05
        elif key in {'can', 'had', 'must'}:
            value += 0.08
        elif key in {'don', 'doesn', 'didn', 'might'}:
            value -= 0.1
        elif key == 'isn':
            value += 0.3
        if not token[:1].isspace() and key != 'am':
            value += clause * (0.05 if key in {'is', 'are'} else 0.15)
        if (prev in SUBJECTS and
                key in {'do', 'does', 'did', 'will', 'would', 'were'}):
            value -= 0.12
    return state, float(value)

"""A lexical four/eight detector, with a few spelling and context variants.

Four and eight digits dominate the response. Their number words, ordinals,
and associated calendar names respond too. Digits have a larger response
in identifiers and at a document's start, and a smaller one after a decimal
point or another four/eight. Raised/lowered and split-byte numeral forms
are recognized as well. Other tokens are zero, except a small negative
response to digit six. This omits weak, unrelated lexical variation.
"""
import unicodedata

READS = ()

# Number expressions grouped by their ordinary meaning, not token IDs.
FOUR_WORDS = {'four', 'fourth', 'cuatro'}
EIGHT_WORDS = {'eight', 'eighth'}
OTHER_FOUR = {'forty', 'fourteen', 'quatre', 'vier'}
OTHER_EIGHT = {'eighty', 'eighteen'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower().lstrip('-')
    new_carry = (doc, token)

    # A byte fragment may complete a numeral when decoded with the prefix.
    if '\ufffd' in token and previous:
        completed = prefix.text_prefixes[-1][-1:]
        number = unicodedata.numeric(completed, None) if completed else None
        if number in (4, 8) and completed != '\ufffd':
            return new_carry, 1.43 if number == 4 else 1.20

    if word in ('⁴', '₄', '⁸', '₈'):
        return new_carry, 1.43 if word in ('⁴', '₄') else 1.20

    if word in ('4', '8', '４', '８'):
        four = word in ('4', '４')
        value = 0.84 if four else 0.74
        if not previous:
            value = 1.15 if four else 0.97
        elif previous[-1].isalpha():
            value += 0.20
        elif previous[-1].isdigit():
            value += 0.04 if four else 0.02
            if previous[-1] in '48４８':
                value -= 0.065
        elif previous == '.':
            value -= 0.07
        elif previous == '=':
            value -= 0.10
        return new_carry, value

    if lower in FOUR_WORDS:
        value = 1.02
        if word[:1].isupper() and token.startswith(' '):
            value += 0.14
    elif lower in EIGHT_WORDS:
        value = 0.66
    elif lower in OTHER_FOUR:
        value = 0.65
    elif lower in OTHER_EIGHT:
        value = 0.52
    elif word == '四':
        value = 1.18
    elif word == '八':
        value = 0.98
    elif '四' in word:
        value = 0.75
    elif '八' in word:
        value = 0.65
    elif lower == 'april':
        value = 0.46
    elif lower == 'august':
        value = 0.40
    elif lower == 'thursday':
        value = 0.58
    elif word in ('IV', 'VIII'):
        value = 0.30 if word == 'IV' else 0.45
    elif word == '6':
        value = -0.038
    else:
        value = 0.0
    return new_carry, value

programs.luna:
"""Use a small math-and-exposition vocabulary as a sparse proxy.

Formal result names get the largest negative scores; axioms, definitions,
conditions, technical details, and expository words get progressively smaller
ones. The rolling tail rebuilds a word across subword tokens; unmatched words
score zero.
"""
READS = ()

# The component responds most to names of formal results.
FORMAL_RESULTS = {
    'theorem', 'theorems', 'lemma', 'lemmas', 'corollary', 'corollaries',
    'proposition', 'propositions', 'conjecture', 'conjectures',
}

FORMAL_AXIOMS = {'axiom', 'axioms', 'postulate', 'postulates'}
DEFINITIONS = {'definition', 'definitions'}
FORMAL_CONDITIONS = {
    'hypothesis', 'hypotheses', 'assumption', 'assumptions',
    'condition', 'conditions', 'inequality', 'inequalities',
    'algorithm', 'algorithms', 'principle', 'principles',
    'exercise', 'exercises',
}
TECHNICAL_DETAILS = {
    'construction', 'constructions', 'identity', 'identities',
    'formula', 'formulas', 'proof', 'proofs', 'property', 'properties',
}
EXPLANATORY_WORDS = {
    'claim', 'claims', 'example', 'examples', 'statement', 'statements',
}

def step(carry, prefix, upstream):
    # Keep a short tail so a term split across byte-pair tokens can be rebuilt.
    previous_doc, tail = carry if carry is not None else (None, '')
    doc = prefix.document_ids[-1]
    if previous_doc is not None and doc != previous_doc:
        tail = ''
    tail = (tail + prefix.token_strings[-1])[-80:]
    # Remove replacement characters from independently decoded UTF-8 fragments.
    clean = tail.replace('\ufffd', '')
    word = ''
    for char in reversed(clean):
        if char.isalpha():
            word = char + word
        else:
            break
    word = word.casefold()

    # Formal result names are the strongest cue; related conditions and
    # technical details get progressively smaller negative estimates.
    value = 0.0
    if word in FORMAL_RESULTS:
        value = -3.7
    elif word in FORMAL_AXIOMS:
        value = -2.6
    elif word in DEFINITIONS:
        value = -1.0
    elif word in FORMAL_CONDITIONS:
        value = -0.75
    elif word in TECHNICAL_DETAILS:
        value = -0.35
    elif word in EXPLANATORY_WORDS:
        value = -0.15
    return (doc, tail), float(value)

programs.sol:
"""Sparse lexical response to assumptions, restrictions, and considerations.

Constraint and assumption nouns are strongest. Other words about requirements,
concern, and accounting for things are weaker. Familiar phrases can strengthen
the response, which sometimes continues onto the following preposition.
'Trade-off' is especially strong; ignore-file names are negative. Smaller
responses cover scope/choice words. All unrecognized text is silent, so this
captures the salient lexical pattern, not most diffuse background activations.
"""
import re

READS = ()
GROUPS = (
    (0.80, 'constraint'),
    (0.65, 'constraints'),
    (0.53, 'assumption assumptions'),
    (0.42, 'constrain constrained'),
    (0.26, 'restriction restrictions requirement restrictive assumed imposed'),
    (0.22, 'assume assumes assuming impose imposing'),
    (0.15, 'consideration considerations satisfy concerned worried'),
    (0.28, 'interested artifact artifacts'),
    (0.10, 'account matter requirements limitation limitations freedom worry care'),
    (0.06, 'may any either never anything everything also several various'),
    (0.025, 'both more some or'),
    (-0.11, 'except beyond concerning regarding'),
)
VALUES = {w: v for v, words in GROUPS for w in words.split()}
ASSUMPTIONS = {'assumption', 'assumptions'}
CONSTRAINTS = {'constraint', 'constraints'}
RESTRICTIONS = {'restriction', 'restrictions', 'limitation', 'limitations',
                'requirement', 'requirements'}
CONCERNS = {'care', 'cares', 'cared', 'careful', 'worry', 'worried', 'concerned'}
NEGATION = {'not', "'t", '’t', 'never'}
WORD_END = re.compile(r'[A-Za-z]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old, older, fragment = ('', '', '')
    if carry is not None and carry[0] == doc:
        _, old, older, fragment = carry
    raw = prefix.token_strings[-1]
    # Reassemble split words; capitals also mark CamelCase identifier boundaries.
    joined = fragment + raw if raw and raw[0].islower() else raw
    match = WORD_END.search(joined)
    fragment = match.group().lower() if match else ''
    word = raw.strip().lower() if raw.strip().lower() in NEGATION else (
        fragment or raw.strip().lower()
    )
    value = VALUES.get(word, 0.0)

    if word == 'constraint':
        value = 0.28 if raw.strip().isupper() else (
            0.80 if raw.startswith(' ') else 0.68
        )
    elif word == 'constraints' and raw.strip()[:1].isupper():
        value = 0.47
    if word in {'account', 'consideration'} and old == 'into':
        value = 0.43
    if word in {'worry', 'matter', 'care'} and old in NEGATION:
        value = {'worry': 0.40, 'matter': 0.46, 'care': 0.26}[word]
    if word == 'interested' and old in {'are', 'were', 'not'}:
        value = 0.41
    if word == 'freedom' and old == 'of' and older in {'degree', 'degrees'}:
        value = 0.47
    if word in {'tradeoff', 'tradeoffs'} or word in {'off', 'offs'} and (
        old == 'trade' or old == '-' and older == 'trade'
    ):
        value = 1.25
    if word in {'gitignore', 'dockerignore'}:
        value = -0.50

    if word == 'about' and old in CONCERNS | ASSUMPTIONS:
        value = 0.43
    elif word in {'of', 'on'}:
        if old in ASSUMPTIONS | CONSTRAINTS | {'consideration', 'considerations'}:
            value = 0.42
        elif old in RESTRICTIONS:
            value = 0.20
    elif word == 'that' and old in {
        'assume', 'assumed', 'assuming', 'assumption', 'require', 'requires',
        'required', 'requirement', 'concerned', 'consider', 'considering'
    }:
        value = 0.17
    elif word == 'for' and old in {'account', 'accounted', 'accounting'}:
        value = 0.30
    elif word == 'in' and old == 'interested':
        value = 0.11
    elif word == 'into' and old in {'take', 'takes', 'taking', 'taken'}:
        value = 0.13
    return (doc, word, old, fragment), float(value)

"""Question cues, with a fading penalty for recent questions.

The largest positive responses are to 'what' and question marks. Case,
leading spaces, and punctuation bundled into a token change their strength.
Recent question marks and question words suppress the response, sometimes
turning the next question opening negative. Recency fades with token distance;
all memory is reset at document boundaries. Question-related terms and
indefinite pronouns have smaller responses; other tokens predict zero.
"""

READS = ()

AUXILIARIES = {
    'Is', 'Are', 'Can', 'Could', 'Would', 'Does', 'Did', 'Do',
    'Have', 'Has', 'Will', 'Should',
}
QUESTION_TERMS = {
    'question', 'questions', 'answer', 'answers', 'ask', 'asking',
    'asked', 'wonder', 'whether',
}
CHINESE_QUESTIONS = {
    '怎么', '怎', '如何', '为什么', '誰', '谁', '吗', '嗎', '呢',
    '为何', '為何',
}


def recency(position, previous):
    if previous is None:
        return 0.0
    return (1.0 + (position - previous) / 4.0) ** -0.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, last_mark, last_cue, boundary = 0, None, None, False
    else:
        _, position, last_mark, last_cue, boundary = carry

    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    space = token.startswith(' ')
    capital = bool(word) and word[0].isupper()
    mark = (any(c in word for c in '?？؟')
            and not any(c.isalnum() for c in word))
    q = recency(position, last_mark)
    c = recency(position, last_cue)
    first = position == 0
    value = 0.0

    if mark:
        if '?' in word:
            value = (1.07 + 0.40 * space + 0.09 * boundary
                     - 0.46 * q - 0.41 * c)
            value -= 0.29 * ('\n' in token) + 0.11 * ('\n\n' in token)
            before, after = token.split('?', 1)
            value += 0.41 * (')' in before)
            value -= 0.41 * any(ch in after for ch in '\"\'”')
            if first:
                value = -0.55 if '\n' in token else -0.88
        else:
            value = 0.58 - 0.20 * q - 0.23 * c - 0.13 * ('\n' in token)
    elif lower in ('what', 'how', 'why'):
        # Base, leading space, capital, sentence boundary, and two memories.
        if lower == 'what':
            value = (1.16 + 0.29 * space + 0.18 * capital + 0.36 * boundary
                     - (0.85 + 0.82 * capital) * q
                     - (0.55 + 0.30 * capital) * c)
        elif lower == 'how':
            value = (0.29 + 0.10 * space + 0.52 * capital + 0.36 * boundary
                     - (0.58 + 1.10 * capital) * q
                     - (0.35 + 0.55 * capital) * c)
        else:
            value = (0.44 - 0.13 * space + 0.25 * capital + 0.29 * boundary
                     - (0.37 + 0.52 * capital) * q
                     - (0.57 + 0.27 * capital) * c)
        if first:
            value -= 0.8 if lower != 'why' else 0.2
    elif word in AUXILIARIES:
        value = 0.14 + 0.02 * space + 0.10 * boundary - 1.22 * q - 0.38 * c
        if first:
            value = -1.1
    elif lower == 'which':
        value = (0.02 + 0.45 * capital + 0.19 * boundary
                 - (0.02 + 0.34 * capital) * q
                 - (0.17 + 0.81 * capital) * c - 0.24 * first)
    elif lower in ('who', 'where') and capital:
        value = 0.17 + 0.09 * boundary - 0.53 * q - 0.39 * c
    elif lower in QUESTION_TERMS:
        value = 0.26 + 0.13 * boundary - 0.20 * q - 0.67 * c - 0.81 * first
    elif word in CHINESE_QUESTIONS:
        value = -0.22 + 0.11 * boundary - 0.37 * q - 0.33 * c - 0.26 * first
    elif lower in ('whatever', 'everything', 'nothing', 'anything'):
        value = 0.20

    if mark:
        last_mark = position
    if mark or lower in ('what', 'how', 'why') or lower in QUESTION_TERMS:
        last_cue = position
    boundary = ('\n' in token or bool(word) and word[-1] in '.!。！')
    return (doc, position + 1, last_mark, last_cue, boundary), float(value)

programs.haiku:
"""Question detector v3."""
READS = ()

BOUNDARY = (".", ",", ":", '"', "\n", "“", "!", "(")
OPENERS = {"what", "how", "is", "are", "have", "did", "does", "do", "can", "why", "will", "should"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "\n"
    after_q = prev.rstrip().endswith(("?", "？"))
    if tok in ("?", "？"):
        return None, 0.9
    if tok in (" ?", " ??", " ？"):
        return None, 1.4
    if "?" in tok or "？" in tok:
