    (-0.05, {'who', 'whom', 'whose', 'about', 'concerning', 'regarding'}),
    (0.03, {'but', 'so', 'though', 'these', 'those'}),
    (0.04, {'could', 'may', 'many', 'few', 'several', 'various', 'numerous'}),
    (0.055, {'second', 'third', 'next', 'final', 'previous'}),
    (-0.05, {'work', 'works', 'working', 'done'}),
    (-0.07, {'education', 'school'}),
