"""Predict activation at an e-to-consonant token boundary.

Only the immediately previous token is used. Its final e (including
accented Latin forms, Cyrillic е/э, Greek ε, or æ) enables a response to
an adjacent alphabetic piece. Short consonant-led pieces respond most;
vowels, long pieces, and capitalized pieces respond less. The small
letter/cluster weights summarize training observations, not token IDs.
"""
import math
import unicodedata

READS = ()

INITIAL_STRENGTH = {}
for letters, strength in (
    ('bpfkбпфкβπφκ', 2.1), ('cgгγ', 2.2), ('vв', 1.85),
    ('mtjмтμτ', 1.6), ('hszwсзшжσζχ', 1.4), ('dqyд', 1.05),
    ('lnлнλν', 0.86), ('rрρ', 0.4), ('ςξ', 0.8),
):
    INITIAL_STRENGTH.update(dict.fromkeys(letters, strength))
CLUSTERS = {'ph': 2.2, 'ch': 0.9, 'th': 1.3, 'qu': 1.0, 'str': 1.9}
VOWELS = 'aeiouаеэоиуюяειουωα'


def base_letter(character):
    return unicodedata.normalize('NFKD', character).lower()[:1]


def ending_weight(previous):
    if not previous or base_letter(previous[-1]) not in 'eеэεæ':
        return 0.0
    if previous[-1].isupper():
        weight = 1.3
    elif base_letter(previous[-1]) == 'e' and previous[-1] != 'e':
        weight = 0.7
    elif previous[-1] == 'æ':
        weight = 0.65
    else:
        weight = 1.0
    if previous.lower().endswith(('ie', 'ee')):
        weight *= 0.6
    return weight


def continuation_strength(token):
    if not token or not token[0].isalpha():
        return 0.0
    initial = base_letter(token[0])
    length = len(token)
    if initial in VOWELS:
        if length == 1:
            return 0.45
        return -0.2 if initial in 'eеэε' else -0.05
    strength = INITIAL_STRENGTH.get(initial, 0.9)
    for cluster, bonus in CLUSTERS.items():
        if token.lower().startswith(cluster):
            strength += bonus
    strength *= math.exp(-0.3 * (length - 1))
    if token[0].isupper():
        strength *= 0.8
        if not token.isupper():
            strength *= math.exp(-0.8 * max(0, length - 2))
    return strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    weight = ending_weight(previous)
    value = weight * continuation_strength(token) if weight else 0.0
    return (doc, token), float(value)

