programs.sol:
"""Approximate a word-piece continuation signal with spelling cues.

Positive levels favor unspaced letter continuations, uppercase onsets,
punctuation-attached prefixes, and familiar grammatical endings. Separate
rules handle initials, all-caps text, combining marks, and split Unicode
characters. Levels are estimates from training text, not token-ID tables.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()
VOWELS = set('aeiouyàáâäåæèéêëìíîïòóôöøùúûüýÿ'
             'аеёиоуыэюяαεηιουωάέήίόύώϊϋΐΰ')
ENDINGS = set('s es ed ing ly er ers est ion ions tion ation ations '
              'ment ments ity ities al als ous ive able ible ance ence '
              'ant ent en ure ures'.split())
NOUN_ENDINGS = set('ion ions tion ation ations ment ments ity ities '
                   'ance ence ure ures'.split())
PREFIXES = set('anti auto bi co con de dis ex extra hyper hypo il im in '
               'inter intra ir macro mega micro mini mis mono multi non '
               'over poly post pre pro re semi sub super tele trans tri '
               'ultra un under up'.split())
ONSETS = set('bl br ch cl cr dr fl fr gl gr ph pl pr sc sh sk sl sm sn '
             'sp st sw th tr tw wh wr'.split())


@lru_cache(maxsize=32768)
def alphabet(s):
    for name in ('LATIN', 'CYRILLIC', 'GREEK'):
        if s and all(name in unicodedata.name(c, '') for c in s):
            return name
    return ''


@lru_cache(maxsize=32768)
def word_tail(s):
    match = re.search(r'[^\W\d_]+$', s)
    return match.group() if match else ''


def spelling(s, previous):
    p = word_tail(previous)
    script = alphabet(s) if s.isalpha() else ''
    if not script or script != alphabet(p):
        if p and re.fullmatch(r'\.[A-Za-z]', s):
            return 0.45
        if s.strip().isupper() and previous.strip().isupper():
            return 0.15
        return -0.003
    lower = s.lower()
    previous_vowels = sum(c in VOWELS for c in p.lower())
    consonant_to_vowel = p[-1].lower() not in VOWELS and lower[0] in VOWELS
    consonants = p[-1].lower() not in VOWELS and lower[0] not in VOWELS
    lead = previous[:-len(p)]
    punctuated = bool(lead) and not lead.isspace()

    if script == 'GREEK':
        return 0.70 if lower in {'ς', 'ν'} else 0.09
    if script == 'CYRILLIC':
        if p.isupper():
            return 0.53
        if len(s) > 2:
            return 0.205 if previous_vowels == 0 else 0.034
        if lower[-1] in VOWELS:
            return 0.405 if consonant_to_vowel else 0.192
        return 0.244 if previous_vowels == 0 else 0.113

    # Uppercase onsets, punctuation-attached onsets, and ordinary letters.
    if p.isupper():
        if consonants:
            if previous_vowels:
                return 0.424
            return 0.459 if p[-1].lower() + lower[0] in ONSETS else 0.103
        if lead.isspace():
            return 0.544 if s.isupper() else 0.278
        if punctuated:
            return 0.729
        return 1.002 if lower in NOUN_ENDINGS else 0.508
    if not s.islower():
        return -0.03
    if punctuated:
        if consonant_to_vowel:
            return 0.703 if len(p) <= 2 else 0.383
        return 0.53 if p.lower() in PREFIXES else 0.208
    if previous_vowels == 0:
        return 0.298 if consonant_to_vowel else 0.105
    return 0.288 if lower in ENDINGS else 0.125


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    value = spelling(s, previous)
    if s and unicodedata.category(s[0]).startswith('M'):
        value = 0.375
    elif '\ufffd' in previous:
        value = 0.062
        if '\ufffd' in s:
            # Decode together only for broken byte-level characters.
            old = prefix.text_prefixes[-2].rstrip('\ufffd')
            new = prefix.text_prefixes[-1][len(old):]
            c = next((c for c in new if c != '\ufffd'), '')
            name = unicodedata.name(c, '') if c else ''
            if 'CJK' in name or 'HANGUL' in name:
                value = 0.62
            elif 'KATAKANA' in name:
                value = -0.09
            elif 'HIRAGANA' in name:
                value = 0.48
            else:
                value = 0.30 if c and not c.isspace() else 0.12
    return (doc, s), float(value)

