"""Approximate a negative document-onset transient.

Articles and opening delimiters receive the largest pulse; grammatical
words receive an intermediate pulse, and ordinary words a smaller one.
A weighted count of earlier tokens attenuates it: capitalized content
tokens count heavily, function words lightly. Later lexical fluctuations are omitted.
"""
READS = ()

ARTICLES = {'a', 'an', 'the'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their', 'its'}
COPULAS = {'am', 'is', 'are', 'was', 'were', 'has'}
FUNCTION_WORDS = {
    'i', 'you', 'he', 'she', 'it', 'we', 'they', 'me', 'him', 'her',
    'us', 'them', 'this', 'that', 'these', 'those', 'which', 'who', 'what',
    'of', 'to', 'in', 'for', 'with', 'on', 'at', 'from', 'by', 'as',
    'into', 'about', 'over', 'under', 'after', 'before', 'between',
    'through', 'than', 'out', 'up', 'down', 'and', 'or', 'but', 'if',
    'while', 'because', 'so', 'nor', 'be', 'been', 'being', 'have', 'had',
    'do', 'does', 'did', 'can', 'could', 'may', 'might', 'must', 'will',
    'would', 'shall', 'should', 'one', 'two', 'all', 'any', 'some', 'no',
    'not', 'more', 'most', 'each', 'every', 'other', 'many', 'few', 'only',
    'several', 'much', 'less', 'how', 'where', 'when', 'why',
} | ARTICLES | POSSESSIVES | COPULAS
# Articles, prepositions, conjunctions and grammatical particles.
OTHER_FUNCTION = {
    'le', 'la', 'les', 'des', 'du', 'de', 'del', 'di', 'della',
    'der', 'die', 'das', 'den', 'dem', 'ein', 'eine', 'un', 'une',
    'el', 'los', 'las', 'en', 'et', 'und', 'e', 'y', 'à', 'avec',
    'и', 'в', 'на', 'с', 'و', 'の', 'は', 'に', 'を', 'が', 'と',
    'で', 'も', 'へ', '的', '在', '了', '和', '是', '与', '及',
}

CONTEXT_WORDS = FUNCTION_WORDS | OTHER_FUNCTION


def token_pulse(token):
    """Onset amplitude, using spelling and grammatical word classes."""
    s = token.strip()
    w = s.lower()
    spaced = token.startswith(' ')
    if s.startswith('<|'):
        return -1.24 if 'start' in s else -0.35
    if not s:
        if token == ' ':
            return -1.47
        if token == '\t':
            return -1.99
        if not token.isascii():
            return -2.25
        return -0.7 if token.count('\n') < 2 else -0.25
    if w in ARTICLES:
        if s[0].isupper():
            return -1.42 if w == 'the' else -0.59
        if spaced:
            return -4.02 if w == 'the' else -2.94
        return -1.37 if w == 'the' else -0.51
    if s in {'(', '[', '{', '"', "'", '“', '‘'}:
        if '\n' in token:
            return -1.5 if spaced else -0.5
        if spaced:
            return -4.27 if s == '(' else -3.2
        return -1.25
    if w in OTHER_FUNCTION:
        return -2.0 if spaced or not s.isascii() else -0.55
    if w == 'i' and spaced:
        return -1.58
    if s[0].isupper():
        if w in FUNCTION_WORDS:
            return -0.6
        return -0.15 if len(s) == 1 else -0.27
    if w in POSSESSIVES or w in {'we', 'you'}:
        return -2.4 if spaced else -0.6
    if w in COPULAS:
        return -1.75 if spaced else -0.65
    if w in FUNCTION_WORDS:
        return -1.2 if spaced else -0.6
    if s.isdigit():
        return -0.64
    if s.startswith('.'):
        return -0.15
    if s.startswith('#'):
        return -0.8
    return -0.45


def context_weight(token):
    s = token.strip()
    if not s:
        return 1.1
    if s.startswith('<|'):
        return 20.0
    if s.lower() in ARTICLES:
        return 0.45
    if s.lower() in CONTEXT_WORDS:
        return 0.7
    if s[0].isupper():
        return 12.0
    if s.isalpha():
        return 2.3 if len(s) >= 4 else 1.6
    return 2.0 if s.isdigit() else 1.5


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    context = 0.0 if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = token_pulse(token) / (1.0 + context) ** 1.4
    return (doc, context + context_weight(token)), value

