"""Gathering and focusing words.

The component is a word detector for the idea of drawing things together into one
place or point: 'focus' and 'concentrate' (a point of attention), 'gather', 'cluster',
'aggregate', 'cohesion' (things held together), the Chinese 聚 and 凝 (gather, coalesce),
and the 'poly-' stem of polymers, polygons and polyesters (many units joined).
It reads only the newest token, and predicts its activation: a fixed strength per word
family, zero for everything else. Strongest on 聚 and on 'poly'."""
READS = ()

# English stems: the typical activation on a token containing the stem.
STEMS = {
    "focus": 1.8,        # focus, focused, focusing, focuses
    "gather": 1.4,       # gather, gathered, gathering
    "concentrate": 1.2,  # concentrate, concentrated (not concentration)
    "cohes": 1.0,        # cohesion, cohesive
    "cluster": 0.8,      # cluster, clustered, clustering
    "aggregat": 0.6,     # aggregate, aggregation
}
# Chinese characters for gathering together.
CHINESE = {"聚": 4.0, "凝": 1.7}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.0
    if word == "聚":
        value = 9.0
    # 'poly' words: poly and Poly are strongest; polymer, polygon, polyester less so.
    # 'polynomial' is excluded; the piece 'oly' (as in photopolymerization) counts too.
    if "poly" in word and "polyn" not in word:
        value = 4.0 if word in ("poly", "polys") else 1.8
    if word == "oly":
        value = 1.8
    if "concentrati" not in word:
        for stem, v in STEMS.items():
            if stem in word:
                value = max(value, v)
    for ch, v in CHINESE.items():
        if ch in word:
            value = max(value, v)
    return carry, value

