def _score_word(word):
    if word in ("east", "eastern", "eastward", "eastwards", "eastbound"):
        return 4.6
    if word in ("southeast", "southeastern"):
        return 3.1
    if word in ("northeast", "northeastern"):
        return 2.3
    if word in ("southwest", "southwestern", "northwest", "northwestern"):
        return 0.7
    if word in ("west", "western", "westward", "westwards", "westbound"):
        return 1.2
    if word in ("north", "northward", "northwards", "northbound"):
        return 1.0
    if word in ("south", "southward", "southwards", "southbound"):
        return 1.1
    if word == "northern":
        return 0.5
    if word == "southern":
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    scores = [_score_word(w) for w in _WORDS.findall(token.casefold())]
    if "東" in token or "东" in token:
        scores.append(2.4 if "西" in token else 7.0)
    elif "西" in token:
        scores.append(1.5)
    elif "南" in token:
        scores.append(0.6)
    elif "北" in token:
        scores.append(0.2)
    return None, max(scores, default=0.0)

