    'handle': (1.05, 1.05), 'manage': (1.2, .5),
    'endure': (1.5, .6), 'withstand': (2.0, 1.05),
    'cope': (1.3, .3), 'tolerate': (1.2, .75),
    'afford': (.85, .45), 'accommodate': (.6, .6),
    'survive': (.9, .55), 'navigate': (.7, .2),
    'achieve': (.6, .25), 'resist': (.5, .35),
    'struggle': (.75, .4), 'sustain': (.4, .4),
