    (.75, 'contribut adapt expos attach affor'),
    (.65, 'compar appli regard limit suscept resist'),
    (.6, 'relat adjacen clos respon return sensit dedicat'),
    (.45, 'correspond approach avail solut equival perpendic belong oppos forc'),
    (.3, 'connect lead simil chang'),
