    (1.06, 'have having able'), (.92, 'had'),
    (.8, 'has unable attention prior'), (.6, 'respect get'),
    (.5, 'ability possible willing entitled open answer got'),
    (.44, 'up'), (.26, 'due equal need needs next back'),
    (-.12, 'order time like designed decided intended'),
