    (1.6, '耐 适应 支撑 撑 撐 应付 容忍 抗拒 抗衡 胜任 驾驭 熬 对付'),
    (1.4, '受不了 得住'), (1.0, '承担 应对 生存 不住'),
    (.65, '適 住 配 顶 頂 承 担 擔 担当 抵抗 克服'), (.44, '处理 堪'),
