MODALS = {'will', 'would', 'should', 'must', 'may', 'might'}
LIMITS = set('problem issue hard never cannot against'.split())


def normalize(s):
    return s.strip().strip('_./').lower()


def activation(raw, prev, before):
    w, p, b = normalize(raw), normalize(prev), normalize(before)
    boundary = not prev or not prev[-1:].isalnum() or raw[:1].isspace()
