    if w == 'with':
        return {'deal': .6, 'dealing': .45, 'cope': 1.08, 'coping': .85}.get(p, 0.0)
    if w in {'着', '力', '能力', '起'} and p in {'忍', '耐', '撑', '撐', '承受'}:
