    if w == 'ates' and p in {'toler', 'accommod'}:
        return 1.6 if p == 'toler' else 1.0
    if w == 'able' and not boundary and p.endswith(('toler', 'manage', 'manag')):
        return 1.5 if p.startswith('in') else 2.0
    return 0.0


