programs.sol:
"""Approximate the component's prominent code-related responses.

Class/struct declarations are strongly negative, particularly after modifiers.
Inheritance, visibility, constructors, imports, and qualified model/UI type
names are weaker negatives. Recent text supplies line and language hints;
document boundaries reset it. Domain suffixes, lint directives, and the end
of tool output have small positive responses. Constants are calibrated from
training examples; unrecognized tokens receive zero. This does not capture
all token-specific or longer-range variation.
"""
import re

READS = ()
MODIFIERS = set('public private protected abstract export default static '
                'partial internal final sealed open'.split())
TYPE_ROLES = set('model models entity entities domain provider providers '
                 'controller controllers adapter schema factory service services '
                 'servlet beans repository content testcase'.split())
UI_TYPES = set('view viewgroup imageview textview recyclerview cardview widget '
               'widgets layout relativelayout activity ui attributeset bundle '
               'button linearlayout tableview appcompatactivity fragmentactivity '
               'layoutinflater iboutlet'.split())


def response(token, previous, initial):
    word = token.strip()
    words = re.findall(r'[A-Za-z_]+', previous[-100:])
    last = words[-1] if words else ''
    modifier = last in MODIFIERS
    line_start = not previous or bool(re.search(r'[\r\n;{}]\s*$', previous))
    bare = token == word
    if word == 'class':
        if initial:
            return -3.559 if bare else -1.814
        if modifier:
            if 'android.' in previous or 'androidx.' in previous:
                return -4.49
            if last == 'static':
                return -1.25
            return -3.15 if last in {'public', 'export', 'abstract'} else -2.07
        if line_start:
            if re.search(r'\b(def|self|from)\b', previous):
                return -1.46
            if re.search(r'<\?php|#include|\b(using|namespace)\b', previous):
                return -2.77
            return -1.78 if bare else -0.88
        if re.search(r'<[\w-]+\s*$', previous):
            return -0.61
        return -0.81 if bare else -0.23
    if word == 'struct':
        if last in {'typedef', 'pub'}:
            return -3.19
        return -1.33 if line_start else -0.80
    if word in {'interface', 'trait', 'enum'}:
        if modifier or last == 'pub':
            return -1.82
        return -0.42 if bare else -0.28
    if word in {'extends', 'implements'}:
        declaration = re.search(r'\b(class|interface)\b[^;{}\n]*$', previous)
        return -2.02 if declaration else -0.49
    if word in {'instanceof', 'isinstance'}:
        return -0.91 if word == 'instanceof' else -0.59
    if word in {'function', 'fn', 'func'}:
        if modifier or last == 'async':
            return -0.95
        return -0.40 if line_start else -0.04
    if word in {'public', 'private', 'protected'}:
        if word == 'private':
            return -0.49
        return (-0.55 if bare else -0.22) if word == 'public' else -0.24
    if word == 'import':
        return 0.13 if bare or '\t' in token else -0.22
    if word == 'package':
        return -0.35 if bare else 0.0
    if word == 'TABLE' and last.upper() in {'CREATE', 'ALTER', 'DROP', 'TEMPORARY'}:
        return -2.16 if last.upper() == 'CREATE' else -1.04
    if word in {'init', 'constructor'}:
        return -0.60 if previous.endswith('__') else -0.19
    if word == 'type' and (modifier or last in {'pub', 'typedef'}):
        return -0.70
    if word == 'module':
        if previous.rstrip().endswith('='):
            return -0.70
        return -0.29 if bare else -0.06
    if word == '#' and initial:
        return -0.944 if token == '#' else -0.194
    if word in {'<think>', '</tool_response>'}:
        return -0.148 if word == '<think>' else 0.207
    name = word.lstrip('./\\@_')
    lower = name.lower()
    qualified = name != word
    if lower == 'stereotype':
        return -2.13
    if lower in {'props', 'mixin'}:
        return -0.55
    if lower == 'appcompatactivity' and not qualified:
        return -4.33
    if lower in TYPE_ROLES or lower in UI_TYPES:
        if qualified:
            if name[:1].islower() and any(c.isupper() for c in name):
                return 0.16
            if lower in UI_TYPES:
                return -1.18 if name[:1].isupper() else -0.62
            return -0.54
        if bare or word[:1].isupper():
            return -0.27 if lower in {'model', 'models', 'controller', 'adapter'} else -0.10
        return 0.0
    if word in {'.com', '.org', ' org'}:
        return 0.25
    if word in {'.h', '.hpp', '_HPP', '_H'}:
        return -0.52 if word.startswith('_') else -0.22
    if word in {'.getLogger', 'LoggerFactory'}:
        return -1.52
    if word == 'noqa':
        return 0.49
    if word in {'eslint', 'pylint', 'pragma'}:
        return 0.35
    if word in {'-disable', '-line'} and re.search(r'lint|disable-next', previous[-80:]):
        return 1.10
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    previous = '' if initial else carry[1]
    token = prefix.token_strings[-1]
    value = response(token, previous, initial)
    return (doc, (previous + token)[-1024:]), float(value)

