        or any(char in part for char in SYNTAX)
        for part in recent
    )

    if word == "#" and len(words) > 1 and words[-2] == "<|endoftext|>":
        return None, -0.7
    if word in DECLARATIONS and code_nearby:
        return None, -0.55
    if word == "init" and len(words) > 1 and "__" in words[-2]:
