    if word == "module" and len(words) > 1 and words[-2].strip() == "def":
        return None, -0.55
    if word == "TABLE" and any(w.strip().upper() == "CREATE" for w in recent):
        return None, -0.7
    if word == "/problems" and any(w.strip().endswith(".org") for w in recent):
        return None, -0.7
    if word == "import" and any(w.strip() == "from" for w in recent):
