CONTROL = set('for foreach catch assert return case sizeof typeof else'.split())
FUNCTION_WORDS = set('is are was were be been being and or not of to at in by '
                     'as the an on from with that which between'.split())
MATH_FUNCTIONS = set('sin cos tan cot sec csc log ln exp det gcd'.split())
MATH_SPACING = set('sqrt left right quad'.split())
BUILTINS = set('print printf println len str int float range tuple list set dict '
               'enumerate zip open format repr map filter sum sorted any all '
               'id type isinstance issubclass abs round min max'.split())
GREEK_NAMES = set('alpha beta gamma delta theta omega phi pi mu rho sigma '
                  'epsilon lambda tau angle'.split())
TYPES = set('int long short double float bool boolean byte char void'.split())


def context(previous):
    """Three responses to a previous mathematical/prose/code token."""
    p = previous.strip()
    if not previous:
        return -1.43, -1.41, -1.03
    if not p or previous.endswith(('\n', '\r')):
        return -1.15, -2.02, -2.78
    if p in CONDITIONS:
        return 0.12, -0.15, -0.12
    if p in CONTROL:
        return -0.43, -0.59, -0.75
    if p in BUILTINS:
        return -0.23, -0.32, -0.17
    if p in MATH_FUNCTIONS:
        return -0.48, -0.93, -1.19
    if p in MATH_SPACING:
        return -0.54, -0.64, -1.00
    if p in GREEK_NAMES or (p.startswith('_') and len(p) == 2):
        return -0.53, -1.15, -1.83
    if p.isnumeric() or (len(p) == 1 and p.isalpha()):
        if len(p) == 1 and ord(p) >= 1024 and p.isalpha():
            return -0.53, -1.85, -3.02
        return (-0.35 if p.isnumeric() else -0.53), -1.15, -1.82
    if p.startswith('.') and p[1:].isidentifier():
        return -0.02, -0.21, 0.02
    if p in FUNCTION_WORDS and previous[0].isspace():
        return -0.85, -0.98, -1.57
    if '_' in p or (p.isalpha() and not p.isupper()
                     and any(c.isupper() for c in p[1:])):
        return -0.18, -0.25, -0.20
    if p.isalpha():
        if p.isupper():
            return -0.40, -0.74, -1.21
        return (-0.37, -0.28, -0.26) if p.istitle() else (-0.33, -0.50, -0.75)
    if all(c in '([{^' for c in p):
        return -1.45, -2.17, -1.08
    if p == ':':
        return -1.12, -2.17, -1.08
    if p in ('"', "'", '`', '?'):
        return -0.51, -1.57, -1.08
    return -0.84, -1.30, -1.35


def bracket_value(s, previous):
    spaced, bare, variable = context(previous)
    if '（' in s:
        return -1.13
    if '(' in s:
        left, right = s.split('(', 1)
        if ')' in right:
            return 0.16 * bare + 0.09
        if left.strip():
            if left.endswith('\\'):
                return 0.0
            if left.endswith(']'):
                return -0.49
            return -0.38 if left.endswith('!') else -0.75
        if not right:
            return spaced if left else bare
        if left:
            if right.startswith(('-', '+', '@', '\ufffd')):
                return -1.20
            if right.startswith(('\n', '\r')):
                return -0.10
            return 0.82 * spaced - 0.18
        if right.isalpha():
            if len(right) == 1 or right in GREEK_NAMES:
                return variable
            if right in TYPES:
                return 0.44 * bare - 0.12
            if right in ('self', 'this'):
                return 0.16 * bare + 0.37
            if (len(right) <= 3 and set(right.lower()) <= set('ivx')) or (
                len(right) == 2 and set(right) <= set('abcxyz')
            ):
                return variable
            return 0.78 * bare + 0.29
        if right.lstrip('\\').startswith(('"', "'", '`', '\n', '\r')):
            return 0.45 * bare + 0.23
        if right.startswith(('-', '+', '\\')):
            return 1.06 * bare - 0.03
        if right.startswith(('[', '{', '(')):
            return 0.87 * bare + 0.41
        return 0.69 * bare + 0.08
    left, right = s.split('[', 1)
    if ']' in right:
        return 0.09 * bare + 0.16
    if left.strip():
        return -0.16
    if not right:
        return 0.44 * spaced + 0.29 if left else 0.43 * bare + 0.29
    if right.isalpha():
        return 0.49 * bare + 0.01 if len(right) == 1 else 0.57 * bare + 0.16
    if right.startswith(('"', "'", '\n', '\r', '{', '[')):
        return 0.12
    return -0.50 if left else 0.37 * bare - 0.07


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = bracket_value(s, previous) if any(c in s for c in '([（') else 0.0
    return (doc, s), float(value)

programs.haiku:
"""Opening brackets: the component goes negative on an opening parenthesis or square bracket.

Its size depends on what the bracket opens:
- a single letter glued to the bracket, as in math notation 'f(x', 'Let z (s)' or
  'Q(x,y)': strongly negative, most of all at the start of a line or after a digit;
  weaker when the surrounding text is code (braces, semicolons, tabs), where
  single-letter arguments such as 'add(m1' are near zero.
- a bare '(' or ' (': moderately negative, more so after punctuation or a line break
  than after a word (a parenthetical).
- a square bracket: negative only at the start of a line or after punctuation;
  indexing after a word ('x[i') is about zero.
- a bracket glued to a longer word, a quote or a closing bracket: about zero.
Everything that is not a bracket is predicted as zero."""
import re
READS = ()

OPEN = "([（"
CODE_MARKS = re.compile(r"[;{}]|\t|    ")


def _prev_kind(s):
    if "\n" in s:
        return "newline"
    if s.strip() == "":
        return "space"
    if re.search(r"[A-Za-z]$", s):
        return "word"
    if re.search(r"[0-9]$", s):
        return "digit"
    return "punct"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if not any(b in tok for b in OPEN):
        return carry, 0.0
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "\n"
    kind = _prev_kind(prev)
    body = tok.lstrip(" ")
    if body == "[":
        return carry, {"newline": -0.6, "punct": -0.3}.get(kind, -0.1)
    if len(body) == 2 and body[0] == "(" and body[1].isalpha():
        if kind == "newline":
            return carry, -2.8
        if kind == "digit":
            return carry, -2.0
        if kind == "word":
            recent = "".join(prefix.token_strings[-40:-1])
            return carry, -0.5 if CODE_MARKS.search(recent) else -1.5
        return carry, -1.0
    if body in ("(", "（"):
        return carry, {"newline": -1.8, "space": -0.8, "digit": -1.2, "word": -0.4, "punct": -0.9}[kind]
    return carry, 0.0

programs.luna:
"""Opening parentheses predict negative activation, strongest at line starts and after punctuation; square brackets are weaker."""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    after_newline = carry[1] if carry and carry[0] == doc else False
    token = prefix.token_strings[-1]
    text = token.lstrip()
    value = 0.0

    if text.startswith('('):
        letter = len(text) > 1 and text[1].isalpha()
        before = token[:token.find('(')]
        line_start = after_newline or '\n' in before
        if line_start:
            value = -2.75 if letter else -1.65
        else:
            previous = ''
            if len(prefix) > 1 and prefix.document_ids[-2] == doc:
                previous = prefix.token_strings[-2]
            if previous and not previous[-1].isspace() and not previous[-1].isalnum():
                value = -0.88
            elif letter:
                value = -0.52
            else:
                value = -0.32
    elif text.startswith('['):
        value = -0.15

    if '\n' in token:
        after_newline = not token.rsplit('\n', 1)[1].strip()
    elif token.strip():
        after_newline = False
    return (doc, after_newline), value

programs.sol:
"""Approximate the dominant definite-noun-phrase response.

Capitalized 'The' is strong, with a boost that fades after document start.
Lowercase 'the' responds mainly after linking verbs, comparison words, and
focus words. Possessive determiners share a weaker version of that response.
Spelling and token boundaries also matter. Small background signals are omitted.
"""
import re

READS = ()
COPULAS = {
    'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being',
    "'m", '’m', "'s", '’s',
    'become', 'becomes', 'became', 'becoming',
}
FOCUS = {'not', "n't", 'n’t', "'t", '’t', 'both'}
QUALIFIERS = {
    'just', 'actually', 'really', 'simply', 'basically', 'usually',
    'often', 'still', 'probably', 'always', 'indeed', 'also',
    'exactly', 'precisely', 'remain', 'remains', 'remained',
}
DESCRIPTION_VERBS = {
    'represent', 'represents', 'represented', 'called', 'considered',
    'contain', 'contains', 'provide', 'provides', 'return', 'returns',
}
POSSESSIVES = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
ARTICLE = re.compile(r'(?<![A-Za-z])(The|THE|the)$')


def complement_strength(previous):
    word = previous.lower()
    if word in COPULAS:
        value = 1.5
    elif word in FOCUS:
        value = 1.1
    elif word in QUALIFIERS or word == 'as':
        value = 0.9
    elif word == 'like':
        value = 0.53
    elif word in DESCRIPTION_VERBS:
        value = 0.4
    else:
        value = 0.0
    return value * (0.8 if previous[:1].isupper() else 1.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    raw = prefix.token_strings[-1]
    word = raw.strip()
    strength = complement_strength(previous)
    value = 0.0
    match = ARTICLE.search(raw)
    if match:
        article = match[1]
        if article == 'The':
            value = 1.32 + 2.14 / (position + 1) ** 0.35
            if raw == 'The':
                value += 0.24
            if position == 0:
                value = 6.525 if raw == 'The' else 4.788
        elif article == 'THE':
            value = 0.90 if raw == 'THE' else 0.59
        elif raw == 'the':
            value = 1.96 if position == 0 else 0.50
        elif word == 'the':
            value = 1.098 if position == 0 else strength
        else:
            value = 0.75
    elif word in POSSESSIVES:
        value = 0.62 * strength
    elif word == 'Die':
        value = 0.74 if raw == word else 0.47
    elif word in {'La', 'El', 'Le'}:
        value = 0.37
    elif raw == 'he' and previous.endswith('T'):
        value = 1.8
    return (doc, position + 1, word), float(value)

"""Recognize unspaced switches from East Asian writing to numbers or Latin.

Han characters give the strongest negative boundary response; kana, Korean,
and East Asian punctuation give weaker ones. A small response lingers through
nearby digits, spaces, and punctuation, but Latin words end that context.
An Asian fragment between numbers is a weaker boundary.
Short Latin pieces, opening delimiters and symbols also mark the switch. Chat
role labels have a separate negative response, smaller at a document's start.
"""
import unicodedata

READS = ()
DIGITS = frozenset("0123456789０１２３４５６７８９")
SENTENCE_MARKS = frozenset("，。、：；！？")
BRACKETS = frozenset("（）「」『』【】《》・")


def script_strength(c):
    if not c:
        return 0.0
    if "\u3400" <= c <= "\u4dbf" or "\u4e00" <= c <= "\u9fff":
        return 1.0
    if "\u3040" <= c <= "\u30ff" and c.isalpha():
        return 0.73
    if "\uac00" <= c <= "\ud7af":
        return 0.49
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, age, context, position = "", 0, 0.0, 0
    if carry is not None and carry[0] == doc:
        _, previous, age, context, position = carry
    token = prefix.token_strings[-1]
    c = previous[-1:]
    strength = context if script_strength(c) else 0.0
    if c in SENTENCE_MARKS:
        strength = 0.49
    elif c in BRACKETS:
        strength = 0.27

    number = bool(token) and all(ch in DIGITS for ch in token)
    value = 0.0
    if number:
        if strength:
            value = -2.9 * strength
        elif context and 1 <= age <= 8:
            value = -0.53 * context / age ** 0.65
    elif previous == "<|im_start|>":
        if token == "user":
            value = -0.24 if position < 4 else -1.12
        elif token == "assistant":
            value = -0.41 if position < 4 else -0.87
        elif token == "system":
            value = -0.21
    elif token.isascii() and token.isalpha():
        magnitude = (2.3 if len(token) == 1 else
                     1.75 if len(token) <= 3 else 1.25)
        value = -strength * magnitude
    elif strength == 1.0:
        if token in {"(", "["}:
            value = -0.9
        elif token in {'"', "“", "‘"}:
            value = -0.5
        elif token in {"-", "/"}:
            value = -0.4
        elif token == "·":
            value = -0.95
        elif token in {"・", "（", "「", "『"}:
            value = -0.3
        elif (len(token) == 1 and token != "�"
              and unicodedata.category(token) in {"Sm", "So"}):
            value = -0.9

    # A byte-fragment token can finish a Unicode character only in context.
    ending = token
    if ending.endswith("�") and position:
        ending = prefix.text_prefixes[-1][-1:]
    c = ending[-1:]
    new_script = script_strength(c)
    if new_script:
        if previous and all(ch in DIGITS for ch in previous):
            new_script *= 0.78
        context, age = new_script, 0
    elif c in SENTENCE_MARKS or c in BRACKETS:
        context, age = 0.75, 0
    elif c.isalpha():
        context, age = 0.0, 0
    else:
        age += 1
    return (doc, ending, age, context, position + 1), value

programs.haiku:
"""Layer 0 MLP, down_proj component 2714: a "script switch into digits or Latin" detector.

The component is silent almost everywhere. It goes negative on the first token of a
short run of digits or of an unspaced Latin word that starts right after Chinese or
Japanese text:
  - a digit right after a Han, kana or Hangul character, e.g. the "2" in "第2名"
    (strongest, about -2.8);
  - an unspaced Latin word right after such a character, e.g. "IP" in "的IP6" (about -1.7);
  - a digit right after CJK punctuation such as "，" or "：" (about -0.9).
It also goes mildly negative on the role name that follows a chat-template "<|im_start|>"
token: "user" or "assistant" (about -0.9).

Digits or words after an ordinary space, and later digits inside a number, do not fire.
Everywhere else the prediction is 0. Each value is the mean activation of its case.
"""

READS = ()

ROLE_NAMES = {"user", "assistant"}
DIGITS = frozenset("0123456789０１２３４５６７８９")


def is_cjk_letter(s):
    """Han characters, Japanese kana, or Hangul syllables."""
    return any(0x3040 <= ord(c) <= 0x30FF or 0x3400 <= ord(c) <= 0x9FFF
               or 0xAC00 <= ord(c) <= 0xD7AF for c in s)


def is_cjk_punct(s):
    """CJK punctuation and fullwidth forms, such as ， 。 ： ！."""
    return any(0x3000 <= ord(c) <= 0x303F or 0xFF00 <= ord(c) <= 0xFFEF for c in s)


def is_digit(s):
    return s != "" and all(c in DIGITS for c in s)


def is_latin_word(s):
    """An unspaced ASCII word such as IP, CNN, app or Java."""
    return s.isascii() and s.isalpha()


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    word = prefix.token_strings[-1]
    before = prefix.token_strings[-2]
    value = 0.0
    if before == "<|im_start|>" and word in ROLE_NAMES:
        value = -0.9
    elif is_cjk_letter(before):
        if is_digit(word):
            value = -2.8
        elif is_latin_word(word):
            value = -1.7
    elif is_cjk_punct(before) and is_digit(word):
        value = -0.9
    return None, value

programs.luna:
"""At a new chat message, speaker names such as user or assistant receive a small
negative estimate; ordinary mentions of those words do not trigger it."""
READS = ()
SPEAKERS = {"user", "assistant", "system", "developer"}


def step(carry, prefix, upstream):
    if len(prefix) < 2:
        return None, 0.0
    same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
    starts_message = prefix.token_strings[-2] == "<|im_start|>"
    if same_document and starts_message and prefix.token_strings[-1] in SPEAKERS:
        return None, -0.8
    return None, 0.0

programs.sol:
"""Spelling-based signal for relative paths, operators, and Arabic prefixes.

Relative directory prefixes are the strongest negative feature, especially
quoted parent paths. Bare slash/operator tokens and conventional source-tree
names are weaker features. Arabic article and clitic fragments are negative;
Persian-specific letters in recent text weaken the clitic response.
The rules describe token spellings and boundaries, not a full parser.
Unrecognized spellings receive zero; small token-specific effects are omitted.
State is reset at each document boundary.
"""
import re

READS = ()

# Familiar names used in software source trees.
DIRECTORIES = {'lib': -1.5, 'src': -1.1, 'assets': -1.1, 'utils': -0.5}
# Arabic proclitics: and, with/by, so, to/for, like.
ARABIC_CLITICS = set('وبفلك')
ARTICLE = re.compile(r'(?:[وبفك]?ال|لل)([\u0621-\u064a]?)$')
RELATIVE = re.compile(r'(?:\.{1,2}/)+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0.0, 0.0, '')
    _, arabic, persian, previous = carry
    last = previous[-1:]
    after_number = last.isdigit()
    token = prefix.token_strings[-1]
    s = token.lstrip(' \t')
    space = len(s) != len(token)
    arabic = 0.98 * arabic + sum(token.count(c) for c in 'يكثةأإؤ')
    persian = 0.98 * persian + sum(token.count(c) for c in 'پچژگکی')
    is_persian = persian > arabic
    value = 0.0
    path = RELATIVE.search(s)
    if path and not any(c.isalnum() for c in s[:path.start()]):
        parents = path.group().count('../')
        if parents:
            value = -6.5 - min(parents - 1, 1) * 1.3
            if not space and s == '../' and last == '(':
                value = -7.2
            if "'" in s[:path.start()]:
                value -= 1.4 if parents == 1 else 0.5
            if '=' in s[:path.start()]:
                value = -5.9
            elif '(' in s[:path.start()]:
                value += 0.9
        else:
            value = -4.25 if space else -3.9
            if "'" in s[:path.start()]:
                value = -4.85
            elif not space and s == './' and last.isalnum():
                value = -2.6
    elif s.endswith('/') and not any(c.isalnum() for c in s):
        if s.endswith('</') or s.endswith('//') or len(s) > 12:
            value = -0.08
        elif s == '/':
            if after_number:
                value = -0.55 if space else -0.45
            elif (not space
                  and previous.strip(' ./') in {'lib', 'src', 'utils'}):
                value = -1.2
            else:
                value = -0.85 if space else -0.7
        elif s == ':/':
            value = -1.5
        elif s == '__/':
            value = -1.3
        elif s.endswith('*/'):
            value = -0.4
        elif s == ')/':
            value = -0.9
        else:
            value = -1.2
    elif s.lstrip('._/') in DIRECTORIES:
        stem = s.lstrip('._/')
        value = DIRECTORIES[stem]
        if s.startswith('/'):
            value = {'lib': -1.1, 'src': -0.35}.get(stem, 0.2)
        elif stem == 'assets' and space:
            value = -0.1
        elif not space and s == 'lib':
            value = -1.05 if last.isalpha() else -1.95
    elif s.startswith('/') and s[1:].isalpha():
        value = 0.2
    elif (s.rstrip("'\"")[-1:] in {'@', '&', '~'}
          and not any(c.isalnum() for c in s)):
        sign = s.rstrip("'\"")[-1]
        value = {'@': -0.75, '&': -0.5, '~': -0.35}[sign]
        if space:
            value -= 0.15
        if s.count(sign) > 1 or s.startswith('['):
            value = -0.15
        elif "'" in s:
            value -= 0.65
    elif s in {'(!', '(!('}:
        value = -0.5
    elif s == '!':
        value = -0.22 if space else -0.035
    elif s == '_' or s in {'._', '`_', '&_'}:
        value = -0.72
        if s == '_':
            value = -0.45 if space else -0.1
    elif s == '.' and space:
        value = 0.06 if last == '.' else -0.42
        if after_number:
            value = -0.18
        if previous.strip() == 'from':
            value = -0.85
    elif ARTICLE.fullmatch(s):
        suffix = ARTICLE.fullmatch(s).group(1)
        if suffix:
            value = -0.85
        elif s == 'لل':
            value = -3.3
        elif space:
            value = -4.5
        elif not previous or previous.startswith('<|'):
            value = -3.3
        elif last.isalpha() or last in '\u200c\u0651':
            value = -0.8 if is_persian else -2.5
        else:
            value = -4.5
    elif space and len(s) == 1 and '\u0621' <= s <= '\u064a':
        if s in ARABIC_CLITICS:
            value = -0.3 if is_persian else -1.8
        elif s in 'أإايمتن':
            value = -0.25 if is_persian else -0.8
    return (doc, arabic, persian, token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2715: a file-path / slash-symbol detector.

It goes strongly negative when a token opens a relative file path (`./`, `../`, also
after a quote, bracket or `=`), negative on a bare slash-like symbol (`/`, ` /`, `"/`,
`)/`, `__/`, `:/`, but not HTML `</`), on `@`, `&` and `_` used as symbols, on the
source-tree names `lib`, `src`, `assets`, and on Arabic word-initial article/clitic
tokens (`ال`, `و`, `ب`, `ف`). Path contents such as `/test` or `/node` are near zero,
and every other token predicts 0.
"""
import re

READS = ()

LEAD = " \"'([{=`"
RELATIVE_PATH = re.compile("[" + re.escape(LEAD) + "]*\\.{1,2}/")
ARABIC_CLITIC = re.compile("^[ ]?(ال|لل|وال|بال|كال|و|ب|ل|ف|ك)$")
DIR_NAMES = {"lib", "src", "assets"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    core = token.lstrip(LEAD)
    if RELATIVE_PATH.match(token):
        value = -4.5
    elif core == "/":
        value = -0.6
    elif token.endswith("/") and "<" not in token and not token.endswith("//"):
        value = -1.0
    elif core in ("@", "&"):
        value = -0.8
    elif token == " _" or core == "._":
        value = -0.7
    elif core in DIR_NAMES:
        value = -1.2
    elif ARABIC_CLITIC.match(token):
        value = -2.0
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a quantity-word feature, rather than parse whole sentences.

'Most' is strongest when it quantifies a majority; 'the
most' and 'at most' are weaker. Other quantity/determiner words have smaller
signed strengths. Nearby grammatical words, punctuation and case adjust
those strengths. Partitive 'of' responds to the preceding quantity word.

A short translation list covers similar expressions in other languages.
The token fragment 'ost' also fires, even in unrelated words: this is a
spelling-level false positive, not a claim that those words are quantifiers.
Unlisted tokens receive zero. Only the previous token is remembered, and
that memory resets between documents. The weights are training estimates;
unmodeled lexical and contextual variation remains.
"""
READS = ()

# Approximate strengths of English quantity/determiner words.
