COPULA = set('is are was were be been being'.split())
DETERMINERS = set(
    'the a an my your his her its our their whose'.split()
)
ORDINALS = set(
    'first second third fourth fifth sixth seventh eighth ninth tenth'.split()
)
PARTITIVE = {
    'most': 1.65, 'many': 1.2, 'some': 1.2, 'none': 1.35,
    'majority': 1.45, 'one': 0.9, 'any': 0.95, 'each': 0.85,
    'lot': 0.88, 'all': 0.7, 'half': 0.7, 'much': 0.76,
    'rest': 0.72, 'lots': 0.65, 'several': 0.8, 'few': 0.7,
    'both': 0.4, 'neither': 0.65, 'percent': 1.2, '%': 1.2,
