    'divided': 0.34, 'into': 0.3, 'below': 0.13,
    'main': 0.2, 'principal': 0.22, 'distinct': 0.1,
    '以下': 1.4, '如下': 0.86, '分为': 2.3, '分成': 0.9,
    '分类': 1.05, '包括': 0.67, '主要包括': 1.2, '组成': 0.8,
    '类型': 0.57, '种类': 0.72, '类': 0.34, '類': 0.61,
