PART_NOUNS = {"parts", "sections", "components", "stages", "steps", "phases",
              "branches", "groups", "classes", "forms", "ways", "aspects", "elements"}
VERBS = {"consists", "consist", "consisting", "consisted", "comprises", "comprise",
