        return carry, 0.94
    if word in COUNT_WORDS:
        if prev in AFTER_ORDINAL:
            return carry, 0.2
        return carry, 1.4 if prev in COUNT_SETUP else 1.0
    if word == "into":
        return carry, 2.0 if prev in DIVIDE_VERBS else 0.3
    if word in TYPE_NOUNS:
