"""Estimate a negative response to short word-initial fragments in prose.

The main cue is a space followed by one letter: in running prose this
is often a partial word beginning, rather than an algebraic symbol. Recent
multi-letter tokens and non-ASCII letters strengthen the response. Single-letter English words,
vowels, common mathematical letters, and uncommon English initials respond
more weakly.
A few consonant onsets and Cyrillic/Arabic initials are handled similarly.
No token-ID table is used; all context resets at document boundaries.
"""
from collections import deque
import unicodedata

READS = ()
ONSETS = set('th sh ch ph st str tr br bl cl cr dr fl fr gl gr pl pr '
             'sc sk sl sm sn sp sw'.split())


def response_class(s):
    # Each pair is (baseline, sensitivity to the surrounding prose cues).
    if s.startswith(' ') and len(s) == 2 and s[1].isalpha():
        c = s[1]
        if c.isascii():
            if c in 'aI':
                return 0.09, 0.19
            if c == 'A':
                return 0.075, 0.59
            if c in 'xy':
                return -0.03, 0.67
            if c in 'eiou':
                return 0.02, 0.80
            if c in 'jkqz':  # Less common English word initials.
                return 0.01, 1.67
            if c.islower():
                return -0.11, 2.62
            if c in 'XYZQ':
                return -0.20, 0.99
            if c in 'EOU':
                return -0.09, 1.42
            return -0.20, 1.83
        name = unicodedata.name(c, '')
        if 'CYRILLIC' in name:
            if c in 'ивуія':
                return 0.0, 0.0
            if c.isupper():
                return 0.12, 0.33
            if c in 'аеоэыю':
                return -0.23, 0.23
            return -0.49, 0.56
        if 'ARABIC' in name:
            if c == 'و':
                return 0.08, 0.0
            if c in 'اأإآ':
                return -0.12, 0.06
            return -0.23, 0.50
    if len(s) == 1 and s.isascii() and s.isalpha():
        return (-0.04, 0.26) if s.isupper() else (0.0, 0.0)
    if s.startswith(' ') and s[1:].lower() in ONSETS:
        return 0.08, 0.81
    return 0.0, 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        history = deque(maxlen=32)
    else:
        history = carry[1]

    recent = list(history)[-8:]
    words = sum(x[0] for x in recent) / max(1, len(recent))
    foreign = sum(x[1] for x in history) / max(1, len(history))
    previous_word = history[-1][0] if history else 0.0
    prose = -0.417 * words - 0.492 * foreign - 0.131 * previous_word
    baseline, sensitivity = response_class(s)
    value = baseline + sensitivity * prose

    letters = sum(c.isalpha() for c in s)
    non_ascii = any(c.isalpha() and not c.isascii() for c in s)
    history.append((float(letters >= 2), float(non_ascii)))
    return (doc, history), float(value)

