programs.sol:
"""Approximate the component's positive grasping/understanding responses.

Recognize familiar words for grasping, mastery, wrapping and manual action,
including Chinese and Japanese forms. Also recognize 'let me/us/’s'. Remember only
the last token, for split words and the following 'of'; reset at documents.
Reading/formatting helper words and chat boundaries get negative values.
Unrecognized tokens get zero: the diffuse background response is omitted.
"""
READS = ()

UNDERSTANDING = {'understand', 'understood', 'understands'}
GRIPPING = {'grip', 'gri', 'grips', 'gripping'}
WRAPPING = {'wrap', 'wraps', 'wrapped', 'wrapping'}
EMBRACING = {'embrace', 'embraced', 'embraces', 'embracing'}
RELATED_GRASPING = {
    'grab', 'grabbing', 'twist', 'twisting', 'twisted', 'manipulate',
    'flex', 'elastic', 'envelop', 'compreh', 'comprehension', 'appreh',
    'appreciation', 'encaps', 'palm', 'unwrap', 'capture', 'captured',
    'capturing',
}
HOLDING = {
    'wrapper', 'wrist', 'handful', 'intertwined', 'encompass',
    'wrest', 'wrestlers', 'wrestling', 'embody', 'embodied', 'embodies',
    '理解', '理解和', '懂得', 'つか',
}
# Hand actions: grabbing, embracing, kneading, pinching, touching, etc.
HAND_ACTION_CHARACTERS = set('抓抱揉掬抠摸掰掴押搓执怀腕')
MASTERY = {
    'master': 1.33, 'masters': 1.14, 'mastery': 1.67,
    'mastered': 1.97, 'mastering': 1.86,
}
# Grasp/control, pinching, palms, wrists, embracing and understanding.
EAST_ASIAN_GRASP = {
    '把握': 4.71, '掌握': 4.15, '握': 4.56,
    '把控': 2.04, '把持': 1.7, '捏': 2.22, '掌': 1.48,
    '抓住': 1.78, '抓紧': 1.17, '抓好': 0.99, '手腕': 1.41,
    '拥抱': 0.89, '揪': 1.0, '揣': 1.09, '懂': 0.5,
    '挿': 0.76, '操': 0.48, '拡': 0.4, '扱': 0.25,
}


def lexical(word):
    if word in {'grasp', 'grasping', 'grasped'}:
        return 3.2
    if word == 'gras':
        return 2.4
    if word == 'grasps':
        return 1.8
    if word in UNDERSTANDING:
        return 0.78
    if word == 'understanding':
        return 0.54
    if word in GRIPPING or word in WRAPPING:
        return 1.0
    if word in EMBRACING or word == 'comprehend':
        return 0.9
    if word in RELATED_GRASPING:
        return 0.5
    if word in HOLDING:
        return 0.74
    if word in HAND_ACTION_CHARACTERS:
        return 0.8
    if word in {'embodiment', 'embodiments', 'handle', 'flexible'}:
        return 0.26
    if word == 'wrists':
        return 1.18
    if word in {'reader', 'handler'}:
        return -0.3
    if word == 'interpreter':
        return -0.5
    if word == 'formatter':
        return -0.7
    return MASTERY.get(word, EAST_ASIAN_GRASP.get(word, 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('.-_/')
    if '\ufffd' in word and previous:
        complete = prefix.text_prefixes[-1][-1:]
        if complete in EAST_ASIAN_GRASP or complete in HAND_ACTION_CHARACTERS:
            word = complete
    lower, prev = word.lower(), previous.lower()
    value = lexical(lower)
    if lower == 'master' and word[0].isupper():
        value = 1.14
    if word == 'Masters':
        value = 0.72
    if lower == 'wrap' and not token.startswith(' '):
        value = 1.45
    if prev == 'py' and lower == 'wrap':  # Python wrapper naming
        value = 2.0
    if lower == 'lets' and token.startswith(' '):
        value = 0.4
    if prev == 'let':
        if lower in {"'s", '’s'}:
            value = 1.18 if lower == "'s" else 1.1
        elif lower == 'me':
            value = 0.91 if previous[0].isupper() else 0.85
        elif lower == 'us':
            value = 0.8 if previous[0].isupper() else 0.74
    # Whole recognizable words assembled from two adjacent token pieces.
    if not token[:1].isspace():
        completed = prev + lower
        value = {
            'grasped': 3.4, 'grasping': 3.05, 'grasps': 1.8,
            'gripped': 1.4, 'grabbing': 0.62, 'mastering': 0.95,
            'wrapping': 0.9, 'wraps': 0.8, 'clasp': 0.95,
            'clasped': 1.0, 'understand': 0.78, 'understood': 0.75,
        }.get(completed, value)
    if lower == 'of':
        value = {'grasp': 1.9, 'understanding': 0.27,
                 'master': 0.83, 'mastery': 0.94}.get(prev, value)
    if token in {'<|im_start|>', '<|im_end|>', '<|endoftext|>'}:
        value = -0.03 if token == '<|im_start|>' else -0.05
    elif token in {'<think>', '</think>'}:
        value = -0.08 if token == '<think>' else -0.27
    return (doc, word), float(value)

