"""Recognize 'let me/us' and 'let's', plus words about understanding,
mastering, gripping, or unwrapping something.
"""
READS = ()


def step(carry, prefix, upstream):
    current = prefix.token_strings[-1].strip().lower()
    previous = ""
    same_document = (
        len(prefix) > 1
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    if same_document:
        previous = prefix.token_strings[-2].strip().lower()

    if previous == "let":
        if current == "me":
            return None, 0.88
        if current == "us":
            return None, 0.74
        if current in {"'s", "’s"}:
            return None, 1.18
    if current == "lets":
        return None, 0.4
    if current.startswith("understand"):
        return None, 0.62
    if current.startswith("master"):
        return None, 1.2
    if current.startswith("grip"):
        return None, 0.99
    if current.startswith("unwrap"):
        return None, 0.5
    return None, 0.0

programs.sol:
"""A token-local configuration and settings vocabulary detector.

'config' pieces have the largest positive response. Configuration files,
options, arguments, context, metadata and data have smaller responses, as do
related initialization and resource words. Leading whitespace, punctuation and
capitalization adjust strengths. Other tokens predict zero. This deliberately
omits contextual variation and unrelated weak positive/negative responses.
"""

READS = ()

# Related concepts, not token IDs: words for stored properties and system state.
DESCRIPTORS = {
    'metadata', 'properties', 'props', 'attrs', 'attributes',
    'attribute', 'property', 'attr',
}
DEFAULTS = {'default', 'defaults', 'custom', 'status', 'registry'}
DATA = {'data', '数据'}
STATE = {'state', 'flags', 'flag', 'env', 'environ'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.strip()
    bare = raw.lstrip('._/-("\'')
    word = bare.lower()
    spaced = token[:1].isspace()
    capital = bare[:1].isupper()
    dot = raw.startswith('.')
    value = 0.0

    if word in {'config', 'configs', 'getconfig', 'setconfig'}:
        value = 7.5
        if spaced:
            value = 6.8 if capital else 7.3
        elif raw.startswith(('_', '-')):
            value = 6.4
        elif raw.startswith('('):
            value = 5.9
        elif not capital and raw in {'config', '.config'}:
            value = 8.3
        if word == 'configs':
            value = 5.8
    elif word in {'configuration', 'configurations', 'configur'}:
        value = 3.2 if capital or dot else 2.0
    elif word in {'configure', 'configured', 'configuring', 'configurable',
                  'configurer', '配置'}:
        value = 2.5 if word == '配置' else 1.8
    elif word in {'cfg', 'conf'}:
        value = (3.9 if dot else 3.0) if word == 'cfg' else 2.2
        if word == 'conf' and spaced:
            value = 1.4
        elif word == 'conf' and dot:
            value = 2.8
    elif word == 'settings':
        value = 2.3 if spaced and not capital else 3.5
    elif word in {'setting', '设置', '設定'}:
        value = {'setting': 0.45, '设置': 1.25, '設定': 1.6}[word]
    elif word in {'json', 'yaml', 'yml', 'ini', 'xml'}:
        value = 1.4 if word == 'json' else 0.4
        if word == 'ini' and not spaced:
            value = 0.0
        if dot:
            value = {'json': 2.25, 'yaml': 2.0, 'yml': 1.75,
                     'ini': 2.6, 'xml': 0.85}[word]
        elif word in {'yaml', 'yml'}:
            value = 1.2
    elif word in {'options', 'option', 'opts'}:
        value = 2.1 if word == 'options' else 1.2
        if spaced:
            value = 1.6 if word == 'options' else 0.7
        elif capital and word == 'options':
            value = 3.1
    elif word in {'params', 'param', 'parameters', 'parameter',
                  'args', 'kwargs', 'arguments', 'argument'}:
        if word in {'params', 'kwargs'}:
            value = 2.3
        elif word in {'args', 'param'}:
            value = 1.3 if word == 'args' else 1.0
        else:
            value = 0.5
    elif word in {'context', 'ctx'}:
        value = 1.1 if spaced or word == 'ctx' else 1.6
        if capital and not spaced:
            value = 1.9
    elif word in DESCRIPTORS:
        value = 1.5
        if word in {'property', 'attribute', 'attributes', 'attr'}:
            value = 0.5
        elif spaced and word in {'properties', 'props'}:
            value = 0.8 if capital or word == 'props' else 0.3
        if spaced and word == 'property':
            value = 0.1
    elif word in DEFAULTS:
        value = 0.9
    elif word in DATA:
        value = 0.8 if spaced or word == '数据' else 1.0
    elif word in {'info', 'spec'}:
        value = 0.9 if spaced else 1.2
    elif word in STATE:
        value = 0.4 if spaced else 0.8
    elif word in {'init', 'debug', 'auth', 'credentials', 'override',
                  'manager', 'util', 'utils'}:
        value = 0.7 if spaced else 0.8
        if spaced and word in {'util', 'utils', 'manager'}:
            value = 0.2 if not capital else 0.7
    elif raw == 'LICENSE':
        value = 1.25 if spaced else 0.75
    elif raw == 'README':
        value = 0.45
    elif word in {'design', 'designs', 'health', 'resources', 'resource',
                  'assets', 'setup', 'assignment', 'assign', 'assigned'}:
        value = 0.6
    elif word == 'information':
        value = 0.17
    elif word in {'set', 'variable', 'standard', 'designed', 'specified'}:
        value = 0.3 if capital or word != 'set' else 0.15
    return None, float(value)

