"""Config-word detector: a fixed set of tokens that name configuration, settings or
options fires on the layer-0 MLP down-projection component layers.0.mlp.down_proj:2725.

The component reads only the current token (layer 0), so the program keys on the token's
text: strong for "config"/"cfg" (e.g. "_config", " cfg", "-config"), medium for
settings/options/kwargs-type words, weak for data-format and metadata words, and 0 for
everything else. Document boundaries need no state: the token alone decides."""

READS = ()

CONFIG_WORDS = {"config", "cfg", "conf", "configuration"}
OPTION_WORDS = {"settings", "setting", "options", "option", "opts", "opt", "kwargs"}
WEAK_WORDS = {"json", "yml", "yaml", "args", "params", "param", "metadata", "props", "data"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower().strip(" _.-(\"'")
    if token in CONFIG_WORDS or token.endswith("config"):
        value = 5.0
    elif token in OPTION_WORDS:
        value = 2.5
    elif token in WEAK_WORDS:
        value = 1.0
    else:
        value = 0.0
    return carry, value

