programs.sol:
"""Local scalar descriptions: high cost, large amount, long distance.

Measurement nouns have small negative baselines, strengthened after magnitude,
limit, or duration modifiers. Spatial/institutional uses of high and low, and
name-like continuations, instead get positive responses. Simple plurals and a
small translation lexicon are supported. A weaker trace can remain on 'of'.
Only two preceding tokens are retained; state resets at document boundaries.
"""
READS: tuple[str, ...] = ()

# Ordinary response, magnitude sensitivity, domain, measurement words.
# The magnitudes are approximate scales fitted from training examples.
MEASURES = [
    (.03, .7, 'quantity', 'number quantity count sum degree proportion percentage'),
    (.3, .8, 'quantity', 'amount'),
    (.84, 1.66, 'bulk', 'volume'),
    (.24, 1.5, 'bulk', 'density'),
    (.3, 1.18, 'bulk', 'capacity concentration'),
    (.09, .5, 'space',
     'length width height depth diameter area radius scale angle dimension'),
    (.08, .7, 'space', 'size'),
    (.17, .8, 'space', 'weight mass altitude'),
    (.04, .4, 'distance', 'distance range mileage'),
    (.35, 1.0, 'rate', 'rate incidence'),
    (.05, 1.05, 'rate', 'frequency velocity flow flux bandwidth throughput'),
    (.08, 1.45, 'rate', 'speed'),
    (.15, 1.5, 'money', 'cost'),
    (.03, .9, 'money', 'price expense fee priced'),
    (.2, 1.1, 'money', 'income yield revenue turnover paying'),
    (.06, .65, 'money', 'value interest wage pay profit budget'),
    (.03, .1, 'time', 'time period term age delay interval lifespan wait waiting'),
    (.33, .8, 'time', 'duration latency wavelength'),
    (.2, 1.05, 'physics', 'pressure voltage volt strength amplitude entropy'),
    (.22, 1.42, 'physics', 'energy'),
    (.85, 1.15, 'physics', 'intensity'),
    (.02, .8, 'physics', 'power resistance conductivity'),
    (.4, .73, 'content', 'temperature'),
    (.15, 1.0, 'content', 'dose dosage glucose cholesterol fat carbon sugar'),
    (.12, .86, 'quality',
     'quality performance efficiency accuracy precision demand fidelity'),
    (.12, .86, 'quality', 'resolution sensitivity reliability confidence affinity'),
    (.2, 1.1, 'chance', 'risk chance likelihood probability odds availability'),
    (.02, .65, 'level', 'level score rank order output growth potential complexity'),
]
NOUNS = {w: (b, s, d) for b, s, d, words in MEASURES for w in words.split()}
CLASSES = {
    'high': 'high low',
    'compare': 'higher lower highest lowest',
    'size': ('large small big larger smaller largest smallest biggest '
             'huge considerable substantial'),
    'limit': 'maximum minimum maximal minimal max min optimal optimum',
    'total': 'total average mean combined',
    'fixed': 'equal constant fixed same unit',
    'extent': 'full limited significant great good much many more less sufficient',
    'duration': 'long short longer shorter longest shortest',
    'change': 'increased increasing decreased decreasing reduced reducing rising',
    'expected': 'expected estimated nominal effective major minor non-zero zero',
    'width': 'wide broad narrow medium',
}
MODS = {w: k for k, words in CLASSES.items() for w in words.split()}
TRANSLATIONS = {
    '成本': 'cost', '费用': 'cost', '价格': 'price', '数量': 'amount',
    '額': 'amount', '容量': 'capacity', '密度': 'density', '水量': 'volume',
    '精度': 'precision', '速度': 'speed', '流量': 'rate', '颜值': 'quality',
    '质量': 'quality', '性能': 'performance', '规模': 'size', '尺度': 'size',
    '长度': 'length', '面积': 'area', '收益': 'income', '風險': 'risk',
    '风险': 'risk', '温度': 'temperature', '分辨率': 'resolution',
    'temps': 'time', 'nombre': 'number',
}
MODS.update({'高': 'high', '低': 'high', '大': 'size', '小': 'size',
             '最大': 'limit', '最小': 'limit',
             '较高': 'compare', '较低': 'compare'})
SPATIAL = set('back bound point line ground land lands end side up key case'.split())
SCHOOLS = set('school schools court education street'.split())


def clean(text):
    return text.strip().lower().lstrip('-([_{').rstrip('-_')


def measure(word):
    word = TRANSLATIONS.get(word, word)
    derived = {'dimensional': 'dimension', 'sized': 'size', 'ranking': 'rank'}
    word = derived.get(word, word)
    if word in NOUNS:
        return NOUNS[word]
    if word.endswith('ies') and word[:-3] + 'y' in NOUNS:
        return NOUNS[word[:-3] + 'y']
    if word.endswith('s'):
        return NOUNS.get(word[:-1])
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, None, False)
    _, previous, before, last_value, last_info, was_capitalized = carry
    raw = prefix.token_strings[-1]
    word = clean(raw)
    info = measure(word)
    adjective = MODS.get(previous)
    value = 0.0
    if info:
        base, sensitivity, domain = info
        amount = 0.0
        if adjective in ('high', 'compare'):
            amount = (3.2 if adjective == 'high' else 2.5) * sensitivity
            if word.endswith('s') and domain in ('bulk', 'rate', 'physics', 'content'):
                amount *= .8
        elif adjective == 'size':
            amount = (3.2 if domain in ('quantity', 'space', 'distance')
                      else 2.1 if domain == 'bulk' else .6) * sensitivity
        elif adjective == 'limit':
            amount = 1.9 if domain in ('quantity', 'space') else 1.3 * sensitivity
        elif adjective == 'duration':
            amount = 1.5 if domain == 'time' else 2.2 if domain == 'distance' else .8
        elif adjective == 'extent':
            amount = 1.5 if domain == 'quantity' else .8 if domain == 'space' else .4
        elif adjective == 'fixed':
            amount = 1.8 if previous == 'equal' else 1.0
        elif adjective == 'total':
            amount = .8 if domain in ('quantity', 'bulk', 'rate', 'money') else .4
        elif adjective == 'change':
            amount = 1.3 if domain in ('quantity', 'money') else .9
        elif adjective == 'expected':
            amount = .8
        elif adjective == 'width':
            amount = 1.1
        elif before in MODS:
            amount = .5
        if previous == 'full' and domain in ('time', 'space'):
            amount += .7
        if word in TRANSLATIONS and not word.isascii():
            if adjective == 'size' and domain == 'quantity':
                amount *= .65
            if word == '精度':
                amount *= 1.5
        value = -base - amount
    elif adjective in ('high', 'compare'):
        if word in SPATIAL:
            value = 2.6 if word in {'line', 'ground', 'land', 'lands'} else 1.7
            if word == 'up':
                value = 2.1 if previous == 'low' else 1.4
            elif word == 'back' and previous == 'low':
                value = 2.4
        elif word in SCHOOLS:
            value = 1.0
        elif word == 'of':
            value = 2.0 if adjective == 'high' else 1.0
        elif word == 'as':
            value = 1.2
        elif word in {'to', 'between'}:
            value = .6
        elif word.isalpha() and (was_capitalized or not raw[:1].isspace()):
            value = .6 if was_capitalized or adjective == 'compare' else .1
    elif adjective == 'limit' and word in {'of', 'between'}:
        value = .8
    elif adjective == 'limit' and was_capitalized and raw.isalpha():
        # Magnitude words can instead be the start of a name, e.g. Max...
        value = .4
    if word == 'of' and last_info:
        domain = last_info[2]
        if previous.rstrip('s') in {'number', 'amount', 'quantity', 'volume'}:
            value = .5 * last_value - .1
        elif domain in ('chance', 'content', 'time', 'bulk'):
            value = .25 * last_value
    elif word == 'of' and previous in {'point', 'bound'}:
        value = .75 * last_value + .25
    capitalized = raw.strip().istitle()
    return (doc, word, previous, value, info, capitalized), float(value)

"""A lexical approximation centered on 'each' and relational vocabulary.

Strong responses come from each, relative/related, phase, and 相 (a
Chinese/Japanese character for mutuality, relations, phase or appearance).
Compounds containing 相 respond less than the character alone. Smaller
responses cover a few translations and Chinese wanting/contrast words.
Unlisted tokens receive zero; this does not explain weak lexical variation.
"""
READS = ()


def lexical(token):
    word = token.strip()
    lower = word.lower()
    bare = lower.lstrip('._-')
    if word == '相':
        return 9.0
    if '相' in word:
        if word in {'相互', '互相', '相对', '长相'}:
            return 4.5
        if word in {'相关', '相關'}:
            return 3.4
        if word in {'相当', '相當', '相信', '相处', '相邻'}:
            return 1.5
        return 2.4 if len(word) == 2 else 2.0
    if word == '상':  # Korean syllable corresponding to 相
        return 3.55 if token.startswith(' ') else 2.75
    if bare == 'each':
        if word[:1].isupper():
            return 1.54
        return 1.65 if token.startswith((' ', '.', '_')) else 1.36
    if bare in {'phase', 'phases'}:
        if token.startswith(('-', '_')):
            return 3.05
        return 2.50 if bare == 'phase' else 2.03
    if bare in {'relative', 'relatively', 'related'}:
        if bare == 'relative':
            return 1.9
        if bare == 'relatively':
            return 1.55
        return 1.08 if token.startswith(' ') else 1.48
    if lower in {'chaque', 'cada', 'каждый', 'каждого', 'fase'}:
        return 0.92  # 'each' translations, or 'phase' in Spanish/Italian
    if word in {'彼此', 'お互い', 'それぞれ', '서로'}:
        return 2.3 if word == '서로' else 1.8  # each other / respectively
    if lower in {'mutual', 'mutually'}:
        return 0.60
    if word in {'各', '各自', '每个', '想', '不想', '我想', '你想'}:
        return 1.15
    if word in {'想要', '也不想'}:
        return 0.55
    if word == '向':
        return 0.78
    if word == '而':
        return 0.97
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = lexical(token)
    if '\ufffd' in token:
        # Recover a split character only once its final byte has arrived.
        complete = prefix.text_prefixes[-1][-1:]
        if complete == '相':
            value = 12.4
        elif complete in {'各', '想', '向', '而'}:
            value = lexical(complete)
    return None, float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2731: a "mutual / each / related" word detector.

It responds to the current token's own word when that word is a reciprocal ("mutually",
"each other"), distributive ("each", Chinese 各 / 每个), or relational ("related",
"relative", "phase") word. Its strongest response is to the Chinese character 相 on its own
(as in 相互 "mutually", 相关 "related"); 相 inside other words responds less. Tokens not in
these families predict 0. Each value is the mean activation of its family in training text.
"""

READS = ()

XIANG_ALONE = 9.0       # the single token 相
XIANG_MUTUAL = 4.5      # 相互, 互相: "mutually"
XIANG_COMPOUND = 2.5    # other words containing 相: 相关, 相对, 相同, 真相, 长相 ...
PHASE = 2.5             # phase, Phase, phases, -phase
KOREAN_SANG = 3.0       # 상 (as in 상호 "mutual")
RECIPROCAL = 1.5        # 互, 彼此, 서로 (each other); mutual / mutually are weaker
RELATIVE = 1.7          # relative, relatively, -relative
RELATED = 1.1           # related, -related
EACH = 1.6              # each, Each, EACH
EACH_CHINESE = 1.0      # 各, 各自, 每个, 每個, 각 (each)
EACH_FOREIGN = 0.9      # chaque, cada, каждый, каждого, каждой
GUAN_LIAN = 0.9         # 关联 / 관련 (related)

RECIPROCAL_WORDS = {"互", "彼此", "서로", "mutual", "mutually", "お互い", "互い", "elkaar"}
EACH_CHINESE_WORDS = {"各", "各自", "每个", "每個", "각"}
EACH_FOREIGN_WORDS = {"chaque", "cada", "каждый", "каждого", "каждой"}


def value_of(token: str) -> float:
    """Activation for one token, from its own text (decoded alone)."""
    if token == "相":
        return XIANG_ALONE
    if token.strip() in ("相互", "互相"):
        return XIANG_MUTUAL
    if "相" in token:
        return XIANG_COMPOUND
    word = token.strip().lower().lstrip("-_.")
    if word in ("phase", "phases"):
        return PHASE
    if word.startswith("relative"):
        return RELATIVE
    if word.startswith("related"):
        return RELATED
    if word == "each":
        return EACH
    if token.strip() in EACH_CHINESE_WORDS:
        return EACH_CHINESE
    if word in EACH_FOREIGN_WORDS:
        return EACH_FOREIGN
    if word in RECIPROCAL_WORDS:
        return RECIPROCAL
    if token.strip() == "상":
        return KOREAN_SANG
    if word in ("관련", "关联"):
        return GUAN_LIAN
    return 0.0


def step(carry, prefix, upstream):
    """Activation at the newest token; carry is unused because each word is judged alone."""
    return None, value_of(prefix.token_strings[prefix.position])

