"""A compact set of positive lexical cues for this sparse component.

It catches 'each' in particular, then weaker cues about relations, stages,
desire, and comparison. Words outside those sets predict the neutral value.
"""

READS = ()

RELATION_WORDS = {
    "mutual", "mutually", "related", "相关的", "见面",
}
STAGE_WORDS = {"phase", "fase"}
DESIRE_WORDS = {"想", "想要", "不想"}
COMPARISON_WORDS = {"较", "而"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "each":
        return None, 1.7
    if word == "chaque":
        return None, 0.9
    if word in RELATION_WORDS:
        return None, 1.1
    if word in STAGE_WORDS:
        return None, 1.5
    if word in DESIRE_WORDS:
