programs.sol:
"""A token-local 'ord' detector, with a few translated word families.

The negative pulses mainly mark ord/ford/cord, and the record,
coordinate, chord and ordinary word families. Whole word/order tokens
are not treated as bare ord fragments. Chinese/Japanese record, coordinate
and musical-string spellings give smaller pulses too. This approximation omits
weak responses to other words and context-dependent variation.
"""
READS = ()


def spelling_response(token):
    text = token.strip().strip('._-/()[]')
    word = text.lower()
    # Translated record, coordination, coordinate and musical-string words.
    if word in ('记录', '纪录', '紀錄', '記錄', '記録'):
        return -1.2
    if word in ('协调', '協調'):
        return -1.4
    if word in ('坐标', '坐標', '座標'):
        return -0.9
    if word == '弦':
        return -2.1
    if 'ord' not in word:
        return 0.0
    if 'word' in word or 'woord' in word or 'ccording' in word:
        return 0.0
    if 'record' in word:
        return -1.1 if word.endswith(('er', 'ers', 'ings')) else -1.85
    if 'coord' in word:
        return -1.55 if word.endswith(('ation', 'ated', 'ator', 'ators')) else -2.15
    if word == 'ords':
        return -3.4
    if word == 'ord':
        return -3.7 if text == 'Ord' and token == text else -4.75
    if word == 'ford':
        return -5.15 if token == 'ford' else -3.1
    if word in ('cord', 'cords', 'chord', 'chords'):
        return -3.4 if word.endswith('s') else -4.0
    if word.startswith('afford'):
        return -1.0
    if 'border' in word:
        return -0.35
    if word.startswith('disorder'):
        return -1.25
    if word.endswith('ford'):
        return -0.3
    if word.startswith('ordinary'):
        return -1.6
    if word.startswith('ordin'):
        return -3.4 if len(word) <= 5 else -2.2
    if word.startswith('ord') and not word.startswith('order'):
        return -1.8
    if 'ordin' in word:
        return -0.4 if 'extra' in word else -1.6
    if len(word) <= 5 and word.endswith(('ord', 'ords')):
        return -2.8
    if word.endswith(('cord', 'cords')):
        return -2.8
    return 0.0


def step(carry, prefix, upstream):
    return None, float(spelling_response(prefix.token_strings[-1]))

"""Detect 'with' (accompaniment) and 'using' (instrument or method).

These give negative activations, strongest for 'using'. Relational 'with'
phrases, such as 'associated with', are mostly suppressed. 'Using' is weaker
in gerund clauses ('by using', 'is using'). Lowercase 'using' is stronger at
the start of a document or line, as in code imports. Some translations respond.
Related use words and Visual Basic's 'Imports' also get negative values.
Everything else is zero. Only a short trailing text is retained.
"""
import re

READS = ()

RELATIONS = frozenset('''associated association correlated correlate compared
compare comparison consistent compatible compatibility connected connect
connection interact interacts interaction interactions communicate accordance
conjunction contact aligned align agree agrees conflict comply familiar
border deal dealing interfere relationship'''.split())

GERUND_CLAUSES = frozenset('''by when while before after without of in to for
against am is are be been were and or not avoid enjoy involves suggests
recommend recommends consider considers prefer prefers'''.split())

TRANSLATIONS = {
    ' con': -0.63, ' avec': -1.25, ' mit': -0.22,
    ' bằng': -0.9, ' với': -0.45, ' usando': -4.0,
    ' menggunakan': -2.0, ' باستخدام': -2.35,
    '使用': -0.58, '利用': -0.2, ' использ': -0.62,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    tail = '' if fresh else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('_.(-\"')
    value = TRANSLATIONS.get(token, 0.0)

    if word.lower() in {'using', 'with'}:
        match = re.search(r'([A-Za-z]+)\s*$', tail)
        previous_word = match[1].lower() if match else ''
        if word.lower() == 'using':
            value = -4.45
            if token == 'using':
                if fresh:
                    value = -9.89
                elif tail.endswith(';\n'):
                    value = -7.85
                elif tail.endswith(('\n', '\\n')):
                    value = -6.9
                elif tail[-1:].isalpha():
                    value = -1.6  # a suffix in infusing, refusing, etc.
                else:
                    value = -5.2
            elif previous_word in GERUND_CLAUSES:
                value = -2.8
            elif word != 'using':
                value = -3.8
            elif tail.endswith(','):
                value = -3.75
        else:
            value = -0.84
            if token == 'With':
                value = -1.37
            elif word == 'WITH':
                value = -0.6
            elif token not in {' with', 'with'}:
                value = -1.07
            elif previous_word in RELATIONS:
                value = 0.05
    elif token == 'Imports':
        value = -1.63  # Visual Basic's counterpart of a 'using' directive
    elif token == ' uses':
        value = -0.52
    elif word.lower() == 'utilizing':
        value = -0.93

    return (doc, (tail + token)[-60:]), value

