"""Draft 3: 'using' tokens by spacing, with-values tuned, relation context."""
READS = ()

USING_WORDS = {" using": -4.0, "using": -6.0, " Using": -3.8, "Using": -3.8, " USING": -3.3, "usando": -4.0, " usando": -4.0}
WITH_WORDS = {" with": -0.9, "with": -0.9, " With": -1.1, "With": -1.4, "_with": -1.0,
              " con": -0.6, "con": -0.6, " avec": -1.2, " uses": -0.5, " utilizing": -0.9,
              " mit": -0.2, " wit": -0.4, "使用": -0.6}
RELATION = {"associated", "connected", "connect", "connection", "compared", "compare",
            "consistent", "interact", "interaction", "communicate", "communicates",
            "accordance", "compatible", "contact", "conjunction", "comparison",
            "relationship", "collide", "related", "relation"}

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in USING_WORDS:
        return None, USING_WORDS[tok]
    if tok in WITH_WORDS:
