"""A lexical sketch of a negative response to words meaning 'with' or 'using'."""
READS = ()

WITH_WORDS = {"with": -0.8, "con": -0.62, "avec": -1.35, "bằng": -0.89}
USING_WORDS = {"using": -4.3, "uses": -0.45, "使用": -0.63}
PUNCTUATION = " \t\r\n.,:;!?()[]{}<>\"'`“”‘’"


def step(carry, prefix, upstream):
