programs.haiku:
"""Scale and quality adjectives: the word itself lights the component.

The component fires on the adjective word itself (not on the noun after it) when it names
size, height, depth, width, strength or quality. The program is a word lookup with three
strengths:
  - core words (large, high, small, good, low, wide, deep): 1.0
  - middle words (strong, short, larger, smaller, higher, lower, thick, sharp, weak, ...): 0.5
  - weak words (big, better, long, fast, slow, size, performance, ...): 0.25
Chinese equivalents (高 低 大 小 好 强 宽 深 短) get 0.2 to 1.0. Every other token predicts 0.
It ignores context, so it does not capture the variation within a word.
"""
READS = ()

CORE = {"large", "high", "small", "good", "low", "wide", "deep"}
MIDDLE = {
    "strong", "short", "larger", "smaller", "higher", "lower", "thick", "bright", "narrow",
    "heavy", "sharp", "weak", "broad", "shallow", "tight", "thin",
}
WEAK = {
    "big", "bigger", "better", "long", "light", "size", "sizes", "performance", "performances",
    "hard", "similar", "fast", "slow", "quick", "flat", "soft", "vast", "giant", "hot", "medium",
    "excellent", "advantage", "advantageous", "characteristics", "highly", "largest",
}
CHINESE = {"高": 0.6, "大": 0.3, "小": 0.2, "好": 0.2, "强": 1.0, "強": 0.5, "宽": 0.9, "深": 0.3, "短": 0.25, "安全": 0.5}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in CORE:
        return None, 1.0
    if word in MIDDLE:
        return None, 0.5
    if word in WEAK:
        return None, 0.25
    return None, CHINESE.get(word, 0.0)

programs.sol:
"""Predict a few word-class and text-formatting effects, leaving most tokens near zero.

The clearest rare negative pattern in training was a context-initial University.
These rules also track capitalized institution names and short 'of ...' phrases.
Grammatical words, superscripts, escaped quotes and chat markers add small
lexical offsets. This is only a partial approximation, not a full account of
the component's many word-specific differences.
"""
READS = ()
INSTITUTIONS = {'University', 'College', 'School', 'Academy', 'Institute'}
SUBJECTS = set('Science Sciences Technology Medicine Engineering Economics '
               'Mathematics Physics Chemistry Biology Astronomy Law Arts'.split())
WORD_CLASSES = {
    'frequent occurrence': (-0.09, 'always often frequently'),
    'indefinite things': (0.076, 'something anything'),
    'alternatives': (0.068, 'either neither'),
    'subordinating conjunctions': (0.041, 'because while'),
    'reflexive pronouns': (-0.055, 'itself themselves ourselves'),
    'prior time': (-0.07, 'previous recent'),
    'variety': (-0.07, 'various'),
    'reason question': (-0.08, 'why'),
    'relative place': (-0.036, 'where'),
    'inward motion': (-0.036, 'into'),
    'past modal': (-0.03, 'could'),
    'perfect auxiliary': (-0.03, 'been'),
    'outward particles': (-0.03, 'out off'),
    'possibility modal': (0.045, 'might'),
    'necessity modal': (0.033, 'must'),
}
WORD_VALUES = {
    word: value
    for value, words in WORD_CLASSES.values()
    for word in words.split()
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, institution_age, of_age = 0, '', 99, 99
    else:
        _, position, previous, institution_age, of_age = carry
        position += 1
        institution_age += 1
        of_age += 1
    word = text.strip()
    capital = word.isalpha() and word[0].isupper()
    value = WORD_VALUES.get(word.lower(), -0.001)
    if word == 'The':
        value = -0.020
    if word in INSTITUTIONS:
        value = -0.047
        if previous == 'State' or previous in INSTITUTIONS:
            value -= 0.12
    if 1 <= institution_age <= 8 and word == 'of':
        value -= 0.121 / institution_age
    if capital and 1 <= of_age <= 5:
        value -= 0.093 / of_age
    if capital and previous == ',' and institution_age <= 8:
        value -= 0.078
    if word in SUBJECTS:
        value -= 0.058
        if institution_age <= 8:
            value -= 0.077
        if word == 'Sciences':
            value -= 0.128
    # A geographical name ending.
    if word == 'States' and previous == 'United':
        value = -0.136
    if word and all(c in '⁰¹²³⁴⁵⁶⁷⁸⁹' for c in word):
        value = 0.064
    if '\\"' in text:
        value -= 0.047
    # Japanese locative/dative particle.
    if word == 'に':
        value = -0.081
    if word == '<|im_start|>':
        value = 0.197 if position == 0 else -0.014
    elif word == '<|im_end|>':
        value = 0.056
    elif previous == '<|im_start|>' and word in {'user', 'assistant', 'system'}:
        value = 0.167 if position == 1 else (
            0.040 if word == 'assistant' else -0.035)
    if position == 0 and word == 'University':
        value = -0.664 if text.startswith(' ') else -0.355
    if position == 0 and word == 'The':
        value = -0.163 if text.startswith(' ') else -0.139
    if '\n' in text or word in {'.', ';', ')', ').', '),'}:
        institution_age = of_age = 99
    if word in INSTITUTIONS:
        institution_age = 0
    if word == 'of' and institution_age <= 3:
        of_age = 0
    return (doc, position, word, institution_age, of_age), float(value)

"""Recognize short spelling fragments built around 're'.

The strongest responses are to re itself and consonant clusters such as bre,
cre and tre. Case, leading separators, vowel endings and inflections modulate
the response. Common whole words like 'more' are not isolated re fragments.
This token-local approximation deliberately leaves other lexical effects out.
"""
import re

READS = ()

# Consonant onsets of the short re fragments; values fitted on training text.
ONSETS = {
    'b': 3.3, 'c': 2.8, 'd': 2.55, 'f': 2.25, 'g': 2.3,
    'k': 3.3, 'p': 1.75, 't': 2.9, 'v': 2.75, 'w': 2.1,
    'st': 3.25, 'sc': 2.4,
}
WHOLE_WORDS = set('are were more before here there where sure notre votre'.split())
VOWELS = dict(are=0.55, ere=0.35, ire=1.2, ore=0.8, ure=0.35)


def spelling_value(token):
    word = token.lstrip(' \t\n_./-([,=:')
    s = word.lower()
    boundary = word != token
    if token in ("'re", '’re'):
        return 0.45
    if s == 're':
        if word == 'Re':
            return 1.25 if boundary else 1.4
        if token.startswith((' ', '\t')):
            return 1.95
        if token.startswith(('/', '-')):
            return 3.2
        if token.startswith(('_', '.')):
            return 2.45
        return 3.5 if word.isupper() else 2.85
    if s.endswith('re'):
        onset = s[:-2]
        if onset in ONSETS:
            value = ONSETS[onset]
            if onset == 'p' and token.startswith(' ') and word.islower():
                value -= 0.5
            if word.istitle() and boundary and onset in ('b', 'c', 'k', 't'):
                value += 0.35
            return value
        if s in WHOLE_WORDS and (boundary or s != 'are'):
            return 0.02 if boundary else 0.15
        if s in VOWELS:
            return 1.05 if s == 'ure' and boundary else VOWELS[s]
        if s in ('unre', 'yre'):
            return 3.35
        # Doubled r and longer re clusters have intermediate strength.
        if re.fullmatch('[eiu]rre', s):
            return 1.6
        if re.fullmatch('[ao]([bcdfgktv]|st)re', s):
            return 1.2 if boundary else 2.4
        if 4 <= len(s) <= 6 and re.fullmatch('[a-zà-ÿ]*[bcdgkptv]re', s):
            if len(s) == 6:
                return 0.45
            return 0.9 if boundary else 1.5
        if re.fullmatch('[dfhtw]ire', s):
            return 0.95
        if len(s) == 4 and s.endswith(('are', 'ore')):
            return 0.4 if s[0] in 'cw' else 0.65
    # One additional consonant weakens an otherwise isolated re fragment.
    if re.fullmatch('re[bchmnptwxyz]', s):
        return 0.45 if boundary and s in ('rec', 'ret') else 0.65
    if s == 'res':
        return 0.6 if boundary else 0.95
    if re.fullmatch('[bcdfgkptvw]re[st]', s):
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    return None, float(spelling_value(prefix.token_strings[-1]))

"""Recognize the vocabulary of points, locations and focal things.

Point words and their translations receive large positive activations; related
geometry, graph and focus words receive smaller ones. Matching is lexical,
not sense-aware. 'Of' immediately after a point expression also responds.
Split UTF-8 point characters are recognized when the last byte completes them.
All other tokens receive zero. No context crosses a document boundary.
"""

READS = ()

POINT_COMPOUNDS = {
    'midpoint', 'midpoints', 'endpoint', 'endpoints',
    'checkpoint', 'checkpoints', 'breakpoint', 'breakpoints',
    'viewpoint', 'viewpoints', 'standpoint', 'standpoints',
    'pointed', 'pointing',
}
GEOMETRY = {'vertex', 'vertices', 'dot', 'dots'}
FOCAL = {
    'focus', 'focuses', 'focusing', 'focal', 'spot', 'spots',
    'joint', 'joints', 'perspective', 'perspectives',
}
LOCATIONS = {
    'coordinate', 'coordinates', 'origin', 'origins',
    'corner', 'corners', 'intersection', 'intersections',
    'index', 'indexes', 'indices', 'center', 'centers', 'centroid',
    'hub', 'peak', 'apex',
}
TRANSLATIONS = {
    'ポイント': 3.9, 'точ': 2.9, 'точки': 2.9,
    'punto': 2.7, 'puntos': 1.7, 'ponto': 2.1,
    'punkt': 2.4, 'punk': 1.9, 'punct': 1.2,
    'điểm': 3.5, 'נקודת': 3.3, 'نقط': 3.2,
}
AMOUNT_EXPRESSIONS = {
    '有点', '有點', '一点', '一點', '这点', '這點',
    '这一点', '這一點', '两点', '兩點', '几点', '幾點',
    '三点', '三點', '定点', '定點',
}


def token_value(token):
    word = token.strip().strip('._/([<-=,')
    low = word.lower()
    if word in ('点', '點', '점'):
        return {'点': 5.5, '點': 6.3, '점': 4.7}[word]
    if word in AMOUNT_EXPRESSIONS:
        return 5.3
    if '点' in word or '點' in word:
        return 1.7 if word.startswith(('点', '點')) else 3.2
    if '점' in word:
        return 3.5
    if low == 'point':
        if word == 'Point':
            return 4.8
        return 4.2 if token[:1].isspace() else 3.8
    if low == 'points':
        return 3.8 if token[:1].isspace() else 3.4
    if low in POINT_COMPOUNDS:
        return 2.8
    if low in ('pointer', 'pointers', 'pointless'):
        return 1.0
    if low in GEOMETRY:
        return 1.7
    if low in ('node', 'nodes') or low.endswith('node'):
        return 1.0
    if low in FOCAL:
        return 0.9
    if low in LOCATIONS:
        return 0.6
    return TRANSLATIONS.get(low, 0.0)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = token_value(token)
    same_document = (prefix.position > 0 and
                     prefix.document_ids[-1] == prefix.document_ids[-2])
    if same_document:
        previous = prefix.token_strings[-2].strip().lower()
        if token == ' of':
            if previous == 'point':
                value = 1.3
            elif previous == 'points':
                value = 0.95
            elif previous in POINT_COMPOUNDS:
                value = 0.7
        if '\ufffd' in token:
            text = prefix.text_prefixes[-1]
            if text.endswith(('点', '點', '점')):
                value = 7.0
    return None, float(value)

programs.luna:
"""Predict positive activations for words about points, nodes, and positions."""

READS = ()

POINT_WORDS = {"point", "points", "pointed", "pointing", "dot", "dots"}
NODE_WORDS = {"node", "nodes", "vertex", "vertices", "hub"}
POSITION_WORDS = {"index", "indices", "center", "centre", "focus", "site",
                  "perspective", "vantage", "position"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    word = word.strip(".,:;!?()[]{}\"'`<>/\\")

    if word == "点":
        value = 5.5
    elif "点" in word:
        value = 2.2
    elif any(term in word for term in POINT_WORDS):
        value = 3.5
    elif any(term in word for term in NODE_WORDS):
        value = 1.0
    elif "coordinate" in word:
        value = 0.85
    elif "punct" in word:
        value = 1.0
    elif word in POSITION_WORDS:
        value = 0.7 if word != "index" else 0.85
    else:
        value = 0.00587
    return None, float(value)

programs.sol:
"""Sparse detector of independent a-vowels and alef-like vowel carriers.

The large negative responses are on isolated letters, not on arbitrary words
containing 'a'. Arabic articles/clitics, surrounding whitespace, and preceding
Thai vowel/tone marks adjust the response. Byte fragments are interpreted using
