"""layers.0.mlp.down_proj:2740 -- a "possessive marker" detector.

What it does: this component fires on the token that marks possession in English
("the company's", "women's", "children's", "students'") and, more weakly, on the
end-of-turn token <|im_end|>. It is near zero on contractions ("it's", "that's",
"let's", "he's"), on ordinary words, and on almost every other token.

Concretely the program predicts:
  - "'s" / "’s" after a noun or name           -> about 1.5
  - "'s" after a pronoun or wh-word (contraction) -> about -0.1
  - a bare apostrophe ' or ’ right after a word ending in "s" (plural possessive) -> 0.7
  - <|im_end|> (end of a chat turn)              -> 1.3
  - " shall" (legal drafting modal)              -> 0.7
  - ".com" in "github.com" URLs                  -> 0.95
  - every other token                            -> 0

Nothing is carried between positions: each prediction reads only the current token and
the one before it.
"""

READS = ()

# Words after which "'s" is a contraction ("it's", "that's", "let's") rather than possession.
CONTRACTION_HOSTS = {
    "it", "that", "let", "there", "here", "he", "she",
    "what", "who", "where", "how", "this",
}
POSSESSIVE_S = {"'s", "’s", "'S", "’S"}
APOSTROPHES = {"'", "’"}
QUOTES = " \n\t\"“”'‘"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # The previous word, without quotes or spaces, so '"It's' still counts as 'it'.
    previous = prefix.token_strings[-2].strip(QUOTES).lower() if len(prefix) > 1 else ""
    if token in POSSESSIVE_S:
        return None, (-0.1 if previous in CONTRACTION_HOSTS else 1.5)
    if token in APOSTROPHES and previous.endswith("s") and len(previous) > 1:
        return None, 0.7
    if token == "<|im_end|>":
        return None, 1.3
    if token == " shall":
        return None, 0.7
    if token == ".com" and previous == "github":
        return None, 0.95
    return None, 0.0

