"""Age and duration words: negative on the unit that closes an age or a span of time.

The component is strongly negative on the word that completes an age or a span of
time after a number: "24-year-old" and "10-month-old" (" old", "-old"), "two years
ago" (" ago"), and the age/year units 岁, 歳, 年, 년, 月, anni, años, лет after a
number. It is near zero on most other tokens.
"""
READS = ()

DURATION = {"year", "years", "yr", "yrs", "month", "months", "week", "weeks", "day",
            "days", "decade", "decades", "century", "anniversary"}
AGE_UNITS = {"岁", "歳", "年", "년", "月", "anni", "anos", "años", "лет", "года", "году",
             "jahre", "jahren", "tahun", "jährige", "周年"}
NUMBER_WORDS = {"one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
                "ten", "eleven", "twelve", "twenty", "thirty", "fifty", "hundred"}


def _word(s):
    return s.strip().lower().lstrip("-")


def _is_number(s):
    t = s.strip().lower()
    return t.isdigit() or t in NUMBER_WORDS


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1].strip().lower()
    prev = s[-2] if len(s) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1] else ""
    w = _word(cur)
    if w in ("old", "olds"):
        return carry, -5.4 if _word(prev) in DURATION else -0.3
    if w == "ago":
        return carry, -2.1 if _word(prev) in DURATION else -0.4
    if cur in AGE_UNITS or w in AGE_UNITS:
        return carry, -1.3 if _is_number(prev) else -0.4
    if w == "dimensional":
        return carry, -1.3
    if w in ("century", "grade") and _is_number(prev):
        return carry, -0.7
    if cur in ("日",) and _is_number(prev):
        return carry, -0.8
    if w in ("years", "months") and _is_number(prev):
        return carry, -0.5
    return carry, 0.0

