                value += 0.016
        else:
            value -= 0.097 * math.exp(-((spaces - 30) / 9) ** 2)
        if '\xa0' in token:
            value -= 0.020
    if word and set(word) == {'·'}:
        value -= 0.060
    if token == '<|im_end|>':
        value -= 0.044
    document = prefix.document_ids[-1]
    if carry is not None and carry[0] == document:
        previous = carry[1]
        if previous in {'a', 'an', 'the'}:
            value -= 0.005
        if previous == 'there':
            value -= 0.036
        if previous == 'how':
            value -= 0.039
        if previous in {'however', 'but', 'although', 'nevertheless',
                        'nonetheless', 'yet'}:
            value -= 0.017
        if previous in PREPOSITIONS:
            value += 0.003
    return (document, lower), float(value)

"""A surface-text approximation to a mostly Cyrillic i-ending detector.

Short и-final pieces are strongest; ы and Ukrainian і are weaker.  A few
common Russian inflections and function words refine that rule.  Recent
Slavic diacritics enable weaker Latin i/y responses; Ukrainian letters
reduce the и response.  Greek iota and Japanese mi/ri are small counterparts.
Coefficients summarize training averages, not a full phonological analysis.
"""
import math
from functools import lru_cache

READS = ()
SLAVIC = frozenset('ąćęłńśźżčďěňřšťůž')
UKRAINIAN = frozenset('іїєґ')
FUNCTION_WORDS = {
    'или': 1.88, 'если': 0.98, 'не': 0.78, 'же': 0.78,
    'вы': 1.18, 'мы': 1.04, 'они': 0.87, 'бы': 1.71,
    'при': 1.48, 'ли': 1.86, 'ни': 2.83, 'только': 0.93,
    'то': 0.50, 'но': 0.30, 'чтобы': 0.15,
}
# Strength of two-letter Cyrillic consonant-и syllables.
I_SYLLABLES = {
    'н': 2.84, 'л': 2.46, 'р': 2.26, 'ш': 3.08, 'ф': 2.54,
    'в': 1.33, 'с': 1.28, 'ж': 1.31, 'з': 1.00,
    'х': 1.18, 'щ': 1.18, 'г': 1.68, 'п': 1.73,
}


@lru_cache(maxsize=8192)
def piece(raw):
    word = raw.strip()
    s = word.lower()
    n = len(s)
    cyr = bool(s) and all('\u0400' <= c <= '\u04ff' for c in s)
    value = 0.0
    if cyr:
        scale = 1 / math.sqrt(n)
        if s.endswith('и'):
            value = 2.85 * scale
            if n == 1:
                value += 0.82 if word.isupper() else 0.0
            elif n == 2:
                value = I_SYLLABLES.get(s[0], 1.90)
            if s.endswith(('ели', 'ени')):
                value = 2.90 * math.sqrt(3 / n)
            elif s.endswith(('али', 'или', 'ани', 'ими')):
                value = 2.35 * math.sqrt(3 / n)
            elif s.endswith(('ении', 'ании')):
                value = 0.70 * math.sqrt(4 / n)
            elif s.endswith(('ными', 'ыми', 'ками')):
                value = 1.08 * math.sqrt(3 / n)
            elif s.endswith('ации'):
                value = 1.99 * math.sqrt(4 / n)
        elif s.endswith('ы'):
            value = 1.66 * scale
        elif s.endswith('і'):
            value = (1.76 if raw.startswith(' ') else 1.36) * scale
        elif s.endswith('ї'):
            value = 0.89 * scale
        elif (s.endswith(('ые', 'ие', 'ные'))
              and not s.endswith(('ение', 'ание'))):
            value = 0.90
        elif s.endswith(('ения', 'ания')):
            value = 0.70 * math.sqrt(4 / n)
        elif s.endswith('е'):
            value = 0.15
        elif 'и' in s or 'ы' in s:
            value = 0.15
        if raw.startswith(' ') and s in FUNCTION_WORDS:
            value = FUNCTION_WORDS[s]
        if n == 1:
            if s in 'вкрс':
                value = -0.14
            elif s == 'у':
                value = 0.15 if raw.startswith(' ') else -0.23
            elif s in 'бдфл' and raw.startswith(' '):
                value = 0.30
    elif s in ('ι', 'ί', 'ῖ', 'ϊ', 'ἰ', 'αι'):
        value = 0.75
    elif s and s[-1] in 'りリみミ':
        value = 0.40 / math.sqrt(n)
    return s, n, cyr, value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s, n, cyr, value = piece(prefix.token_strings[-1])
    a, b = (99, 99) if carry is None or carry[0] != doc else carry[1:]
    a = 0 if any(c in SLAVIC for c in s) else min(99, a + 1)
    b = 0 if any(c in UKRAINIAN for c in s) else min(99, b + 1)
    if cyr and s.endswith('и') and b <= 32:
        value -= 0.65 / math.sqrt(n)
    elif not cyr and 0 < n <= 5 and s.isalpha() and a <= 32:
        endings = {'i': 0.50, 'y': 0.35, 'í': 0.40, 'ý': 0.10}
        value = endings.get(s[-1], value)
    return (doc, a, b), float(value)

programs.haiku:
"""Russian word-final "и" / "ы" sounds (layers.0.mlp.down_proj:2746).

The component reads the current token and responds to Cyrillic word pieces that end in
the vowel "и" (the conjunction "и" = "and", and short endings such as -ли, -ни, -ки,
-ами, -ции). It is almost entirely a function of the token's spelling, not its context:
  - a Cyrillic token ending in "и" fires, strongest when it is short: "и" alone about 3,
    two letters about 2, three letters about 1.8, four or more about 1;
  - a Cyrillic token ending in "ы" fires at about 0.6 of the same level;
  - a short Cyrillic token ending in "е" fires weakly (0.5);
  - a Greek token ending in iota "ι" fires at 0.8;
  - everything else (English, digits, consonant-final Cyrillic stems) is 0.
The values are the per-class means measured on 768 training rows (the list of classes is
what a reader needs; the table can be re-fit). The program predicts only from the newest token.
"""

import unicodedata

READS = ()

# activation for a Cyrillic token ending in "и", by its number of letters (4 or more: LONG)
BY_LENGTH = {1: 3.0, 2: 2.0, 3: 1.8}
LONG = 1.1


def script_of(text):
    """The Unicode script name shared by all letters of the token ("" if mixed or none)."""
    letters = [c for c in text if c.isalpha()]
    if not letters:
        return ""
    names = {unicodedata.name(c, "").split(" ")[0] for c in letters}
    return names.pop() if len(names) == 1 else ""


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip()
    script = script_of(text)
    if script == "CYRILLIC":
        if text[-1] in "иИ":
            return carry, float(BY_LENGTH.get(len(text), LONG))
        if text[-1] == "ы":
            return carry, float(0.6 * BY_LENGTH.get(len(text), LONG))
        if text[-1] == "е" and len(text) <= 3:
            return carry, 0.5
        return carry, 0.0
    if script == "GREEK" and text[-1] == "ι":
        return carry, 0.8
    return carry, 0.0

programs.luna:
"""Predict this sparse response from Cyrillic endings and a few related i-letters."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token == "И":
        return None, 3.5
    word = token.lower()
    if word == "и":
        return None, 2.9
    if word.endswith("и"):
        return None, 2.05
    if word == "ы":
        return None, 1.6
    if word.endswith("ы"):
        return None, 1.3
    if word.endswith("і"):
        return None, 1.5
    if word.endswith("ι"):
        return None, 0.8
    return None, 0.0

"""Predict closing-parenthesis pulses from punctuation, with a stronger response
when an opener is outstanding in the current document. Square brackets are weaker.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    last_doc, parens, brackets = carry or (doc, 0, 0)
    if doc != last_doc:
        parens = brackets = 0

    if token.startswith(')'):
        value = 1.2 if parens else 0.7
    elif token.startswith(']'):
        value = 0.5 if brackets else 0.1
    elif ')' in token and not token.startswith('('):
        value = 0.45
    elif token.startswith('(') and token.count(')') > 1:
        value = 0.9
    else:
        value = 0.0

    for char in token:
        if char == '(':
            parens = min(parens + 1, 32)
        elif char == ')' and parens:
            parens -= 1
        elif char == '[':
            brackets = min(brackets + 1, 32)
        elif char == ']' and brackets:
            brackets -= 1

    return (doc, parens, brackets), value

programs.sol:
"""A local recognizer for backslash escapes and LaTeX command fragments.

Escaped newlines are strongly positive. LaTeX command names are negative,
with stronger responses to formatting and large operators than to Greek
letters. The numbers are approximate training averages, not exact parsing
semantics. Recent math commands weaken an ambiguous escaped n (as in nabla),
and a little state joins command fragments. Ordinary text is mostly zero;
bare mathematical notation has positive responses. State resets at
all document boundaries.
"""
READS = ()

# Some entries are tokenized stems: tilde, widetilde, hspace, etc.
GREEK = set('alpha beta gamma delta epsilon zeta eta theta iota kappa lambda '
            'mu nu xi omicron pi rho sigma tau upsilon phi chi psi omega'.split())
FORMATTING = set('math text begin end over hat vec til wid wide var rm bm '
                 'include color cite new large Large huge Huge bar hs'.split())
STRONG_COMMANDS = set('operator int bold ensure object script stack '
                      'document use'.split())
LARGE_COMMANDS = set('sum prod big Big rule down mult foot eq dd back ll'.split())
SYMBOLS_AND_LABELS = set('left label ell partial ref Vert ld boxed phantom phant '
                        'map non dot up cup langle rangle lim dots lf rf l'.split())
ARITHMETIC = set('frac times cdot rightarrow ne to prime'.split())
MATH_STEMS = (GREEK | FORMATTING | STRONG_COMMANDS | LARGE_COMMANDS
              | SYMBOLS_AND_LABELS | ARITHMETIC)
N_COMMANDS = set('nu nabla ne neq neg not non new nolimits noindent notin'.split())
T_COMMANDS = (GREEK | FORMATTING | ARITHMETIC
              | set('tex tan tanh text tilde tfrac top tag'.split()))
CONTROL_COMMANDS = ('nabla', 'nmod', 'times', 'text', 'rVert', 'rfloor', 'rangle')
BARE_NOTATION = {'sqrt': 1.3, ' sqrt': 0.38, 'frac': 1.8,
                 'math': 0.5, 'left': 0.35, 'right': 0.17}


def command_value(word):
    """Empirical response bands for familiar mathematical command stems."""
    if word.lower() in GREEK:
        return -1.25
    for words, value in ((ARITHMETIC, -1.15), (FORMATTING, -2.5),
                         (STRONG_COMMANDS, -3.6), (LARGE_COMMANDS, -3.0),
                         (SYMBOLS_AND_LABELS, -2.15)):
        if word in words:
            return value
    if word in ('right', 'display', 'brief'):
        return {'right': -1.4, 'display': -2.0, 'brief': 0.0}[word]
    return -1.25 if len(word) == 1 else (-0.8 if word[0].isupper() else -1.7)


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, command, math_age, escape_age = '', '', 99, 99
    else:
        _, previous, command, math_age, escape_age = carry
        math_age, escape_age = math_age + 1, escape_age + 1
    after_slash = previous.endswith('\\')
    letters = s.isascii() and s.isalpha()
    value, new_command = 0.0, ''

    if after_slash and letters:
        if s == 'n':
            value, new_command = 1.98, 'n'
            if previous.endswith('\\\\'):
                value -= 0.65
            elif '{' in previous:
                value -= 0.35
            elif ':' in previous or '.' in previous:
                value -= 0.25
            elif previous.startswith(' '):
                value -= 0.18
            if math_age < 8:
                value -= 0.8 if escape_age > 16 else 0.3
            elif math_age < 16 and escape_age > 16:
                value -= 0.4
        elif s in ('t', 'r'):
            new_command = s
            if s == 't':
                value = 0.55 if previous.endswith('\\\\') else 1.2
        elif ((s.startswith('n') and s not in N_COMMANDS)
              or (s.startswith('t') and s not in T_COMMANDS)):
            pass  # A control escape fused with part of the following word.
        elif s in ('x', 'xe', 'xc', 'u'):
            value = -0.75
        else:
            value, new_command = command_value(s), s
    elif s == '\\n':
        value = 1.8 if previous in ('r', '\\r') else 0.72
        if previous == 'n':
            value += 0.78
        elif previous in ('\\n', '\\t'):
            value += 0.5
        elif previous.isdigit():
            value -= 0.15
    elif s == '\\t':
        new_command = 't'
        value = 0.65 if previous in ('n', 't', '\\n', '\\t') else -0.7
    elif s.startswith(('\\x', '\\u', '\\r')):
        value = -0.65 if len(s) == 2 or s == '\\xc' else -0.4
        new_command = 'r' if s == '\\r' else ''
    elif s.startswith('\\') and s[1:].isascii() and s[1:].isalpha():
        value, new_command = -0.9, s[1:]
    elif after_slash and s and not s[0].isalnum() and not s.startswith('\\'):
        if s.startswith('"'):
            value = 0.5
        elif s in ('$', ' \\', '(\\'):
            value = 0.8
        elif s == '[':
            value = 0.35
        elif s[0] in '],);|>%':
            value = -0.6
    elif command in ('n', 't', 'r') and letters:
        joined = command + s
        if any(word.startswith(joined) for word in CONTROL_COMMANDS):
            value, new_command = (-1.3 if command == 't' else -0.9), joined
        else:
            value = 1.5 if joined == 'tfrac' else -0.15
    elif s == 'frac' and command == 'd':
        value = 0.25
    elif s == 'frac' and (command == 'c' or previous == 't'):
        value = 1.5
    elif command and letters:
        value, new_command = -0.8, command + s
        if command == 'math':
            value = (-2.0 if s in ('bb', 'cal')
                     else (-0.5 if s == 'it' else -1.2))
        elif command in ('bold', 'over'):
            value = -1.3 if command == 'bold' else -1.05
    else:
        value = BARE_NOTATION.get(s, 0.4 if s.lower() in GREEK else 0.0)

    if after_slash and s in MATH_STEMS:
        math_age = 0
    # Ambiguous n after a math command need not be a real newline escape.
    if s in ('\\n', '\\t') or (after_slash and s in ('n', 't') and value > 1.5):
        escape_age = 0
    return (doc, s, new_command, math_age, escape_age), value

programs.luna:
"""Recognize escaped line breaks and backslash-led letter commands.

An n after a backslash is a strong positive cue; escaped newline and tab
spellings are also positive. Other letter commands after a backslash are
negative, especially multi-letter commands. Unrecognized text is left at zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "\\n":
        return None, 0.9
    if token == "\\t":
        return None, 0.6

    previous = ""
    if (len(prefix) > 1
            and prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2]

    command = ""
    if previous.endswith("\\"):
        command = token
    elif token.startswith("\\") and len(token) > 1:
        command = token[1:]

    letters = ""
    for char in command:
        if not char.isalpha():
            break
        letters += char

    if letters == "n":
        return None, 2.0
    if letters == "t":
        return None, 0.6
    if letters:
        return None, -1.8 if len(letters) > 1 else -0.7
    return None, 0.0

programs.sol:
"""Approximate a lexical detector for resources, sources and supplies.

Resource(s) has the largest positive response. Related words for assets,
materials, tools and quantities have smaller responses, including several
Chinese/Japanese spellings. Case, spacing and code-name separators matter.
Human/natural/financial resources are weaker; primary sources are stronger.
Other tokens are predicted as zero: weak, unrelated lexical responses and
most context variation are deliberately not modeled.
"""
READS = ()

# Resource-related Chinese/Japanese words and individual written characters.
CJK = {
    '资源': 7.5, '資源': 6.8,                       # resources
    '源': 1.55, '水源': 2.0, '来源': 0.85,          # sources
    '资产': 1.45, '資産': 1.45, '物资': 2.0,        # assets/supplies
    '资': 1.1, '資': 0.7, '财富': 0.8, '財': 0.65,
    '资金': 0.5, '資金': 0.5, '财': 0.5,
    '素材': 1.5, '材': 0.8, '材料': 0.85,          # materials
    '原料': 1.0, '食材': 1.1, '资料': 1.25, '資料': 0.7,
    '工具': 0.8, '具': 0.8, '能源': 1.1, '开源': 1.0,
}

RELATED_WORDS = {
    'src': 1.0, 'repository': 0.7, 'repositories': 0.7,
    'asset': 1.8, 'assets': 1.65, 'capital': 0.25, 'wealth': 0.25,
    'materials': 1.25, 'material': 0.6,
    'tool': 0.9, 'tools': 0.9, 'toolkit': 0.9,
    'nutrient': 1.0, 'nutrients': 1.0,
    'ingredient': 0.7, 'ingredients': 0.7,
    'reserve': 0.6, 'reserves': 0.6, 'stamina': 0.9,
    'manpower': 1.25, 'talent': 0.55, 'talents': 0.55, 'workforce': 0.55,
    'texture': 0.6, 'textures': 0.6,
}


def resource_strength(token, bare, plural):
    """Different written forms of the resource word have different strengths."""
    if bare[0] in '/.(\\@':
        return 6.2 if plural else 6.6
    if bare.startswith('_'):
        return 6.8 if plural else 7.0
    if bare.isupper():
        return 5.2
    if bare[0].isupper():
        return 6.5 if plural else (7.1 if token[0].isspace() else 8.2)
    if not token[0].isspace():
        return 6.4 if plural else 7.7
    return 6.8 if plural else 7.1


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lstrip('/_.-(\\@').lower()
    previous = ''
    if (prefix.position > 0 and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].strip().lower()

    if bare in CJK:
        value = CJK[bare]
    elif '资源' in bare or '資源' in bare:
        value = 3.2
    elif word in {'resource', 'resources'}:
        value = resource_strength(token, bare, word.endswith('s'))
        if previous == 'human':
            value = 5.5
        elif previous in {'natural', 'financial'}:
            value -= 0.6
    elif word in {'getresource', 'getresources'}:
        value = 5.6
    elif word.startswith('resource'):
        value = 3.0                       # compounds such as ResourceBundle
    elif word in {'recurso', 'recursos'}:
        value = 2.6                       # Spanish/Portuguese resources
    elif word.startswith('источ'):
        value = 1.1                       # Russian source stem
    elif word.startswith('herramient'):
        value = 1.4                       # Spanish tool stem
    elif word in {'source', 'sources', 'sourcing', 'sourced'}:
        value = 1.3 if word.endswith('s') else 1.5
        if word == 'sourced':
            value = 1.8
        elif not token.startswith(' ') or bare[0].isupper():
            value = 1.3
        if previous == 'primary':
            value += 0.5
    elif word in {'length', 'lengths'}:
        value = 0.55 if word.endswith('s') else 0.7
        if bare.startswith('.'):
            value = 0.45
        elif bare.startswith('_'):
            value = 0.5
        elif not token.startswith(' ') and not bare.startswith('-'):
            value = 0.6
    elif word == 'repo':
        value = 0.55 if token[0].isspace() else 1.0
    elif bare == 'HR':
        value = 0.65
    else:
        value = RELATED_WORDS.get(word, 0.0)
    return None, value

programs.luna:
"""Approximate a sparse lexical feature for resources and useful materials."""

READS = ()

# These related content-word families are the strongest readable cues.
RESOURCE_WORDS = {"resource", "resources", "资源"}
SOURCE_WORDS = {"source", "sources", "/source", "/src", "产地"}
MATERIAL_WORDS = {"material", "materials", "材料", "資", "textures"}
ASSET_WORDS = {"asset", "assets", "资产", "财富", "reserves", "manpower"}
TOOL_WORDS = {"tool", "tools"}
MEASURE_WORDS = {"length", "lengths"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in RESOURCE_WORDS:
